from __future__ import annotations

import argparse
from pathlib import Path


ACTION_ADAPTER_CONTENT = 'from __future__ import annotations\n\nimport hashlib\nfrom collections import Counter\nfrom dataclasses import dataclass\nfrom itertools import combinations\nfrom threading import RLock\nfrom typing import Any\n\nfrom .action_hierarchy import (\n    build_action_legality_engine,\n    classify_action_outcome_key,\n    high_level_code_for_key,\n    rebuild_encoded_action_set,\n)\nfrom .schema import (\n    ActionChoice,\n    DecisionContext,\n    DecisionType,\n    EnvConfig,\n    LowLevelActionSpec,\n    Matchup,\n    OptionKind,\n    PublicSlotTarget,\n    StateSnapshot,\n)\n\nOMNI_DICE = 8\nELEMENTAL_DICE = (1, 2, 3, 4, 5, 6, 7)\n\nREQ_VOID = 0\nREQ_ALIGNED = 8\nREQ_ENERGY = 9\nREQ_LEGEND = 10\n_RESULT_RELABEL_CACHE_LIMIT = 2048\n_RESULT_RELABEL_CACHE_LOCK = RLock()\n_RESULT_RELABEL_CACHE: dict[tuple[Any, ...], dict[int, int]] = {}\n_DIRECT_ACTION_LABEL_KINDS = {\n    OptionKind.ACTION_DECLARE_END,\n    OptionKind.ACTION_SWITCH_ACTIVE,\n    OptionKind.ACTION_ELEMENTAL_TUNING,\n}\n\n\n@dataclass(frozen=True)\nclass BuiltDecisionContext:\n    context: DecisionContext\n    payload_by_low_level_code: dict[int, dict[str, Any]]\n    label_by_low_level_code: dict[int, str]\n    low_to_high_code: dict[int, int]\n\n\n@dataclass(frozen=True)\nclass _SpecPayload:\n    spec: LowLevelActionSpec\n    payload: dict[str, Any]\n\n\ndef _spec_payload_dedup_key(item: _SpecPayload) -> tuple[Any, ...]:\n    spec = item.spec\n    return (\n        spec.request_type.value,\n        spec.kind.value,\n        int(spec.subject_definition_id),\n        tuple((target.owner, target.zone, int(target.index)) for target in spec.target_slots),\n        tuple(int(value) for value in sorted(spec.used_dice)),\n        tuple(int(value) for value in sorted(spec.auto_selected_dice)),\n        int(spec.choose_active_slot),\n        int(spec.select_card_definition_id),\n        int(spec.switch_hand_slot_mask),\n        int(spec.reroll_dice_mask),\n        int(spec.discarded_hand_slot),\n        int(spec.discarded_card_definition_id),\n        int(spec.target_dice),\n    )\n\n\ndef _dedupe_spec_payloads(spec_payloads: list[_SpecPayload]) -> tuple[_SpecPayload, ...]:\n    unique: list[_SpecPayload] = []\n    seen: dict[tuple[Any, ...], _SpecPayload] = {}\n    for item in spec_payloads:\n        key = _spec_payload_dedup_key(item)\n        existing = seen.get(key)\n        if existing is not None:\n            # Benign duplicate raw options are common (for example identical card\n            # copies / equivalent tuning branches). Keep the first payload silently\n            # to avoid flooding stdout with index-only dedupe noise.\n            continue\n        seen[key] = item\n        unique.append(item)\n    return tuple(unique)\n\n\ndef encode_choice(built: BuiltDecisionContext, action_code: int) -> dict[str, Any]:\n    if int(action_code) not in built.payload_by_low_level_code:\n        raise KeyError(f"unknown action_code: {action_code}")\n    return dict(built.payload_by_low_level_code[int(action_code)])\n\n\ndef build_decision_context(\n    *,\n    acting_player: int,\n    request_type: DecisionType,\n    request: Any,\n    full_state: StateSnapshot,\n    player_view: StateSnapshot | None,\n    full_state_json: str | None,\n    step_index: int,\n    metadata: dict[str, Any] | None = None,\n    enable_result_based_action_relabel: bool = False,\n) -> BuiltDecisionContext:\n    metadata = metadata or {}\n    builder = {\n        DecisionType.CHOOSE_ACTIVE: _choose_active_specs,\n        DecisionType.SELECT_CARD: _select_card_specs,\n        DecisionType.REROLL_DICE: _reroll_specs,\n        DecisionType.SWITCH_HANDS: _switch_hands_specs,\n        DecisionType.ACTION: _action_specs,\n    }[request_type]\n    spec_payloads, request_payload = builder(\n        request=request,\n        acting_player=acting_player,\n        full_state=full_state,\n        player_view=player_view,\n    )\n    spec_payloads = list(_dedupe_spec_payloads(spec_payloads))\n    legality_engine = build_action_legality_engine()\n    encoded_actions, materialized_specs, low_to_high_code = legality_engine.encode_legal_actions(\n        acting_player=acting_player,\n        visible_state=player_view or full_state,\n        legal_specs=tuple(item.spec for item in spec_payloads),\n    )\n    if (\n        enable_result_based_action_relabel\n        and request_type == DecisionType.ACTION\n        # Online acting/search stays on the pre-state intent taxonomy. Outcome-\n        # based relabel is an offline analysis/training tool and must not sit on\n        # the hot path.\n        and full_state_json\n        and encoded_actions.legal_low_level_codes\n    ):\n        encoded_actions, low_to_high_code = _relabel_action_high_levels_by_result(\n            acting_player=acting_player,\n            full_state_json=full_state_json,\n            full_state=full_state,\n            legal_low_level_codes=encoded_actions.legal_low_level_codes,\n            legal_low_level_mask=encoded_actions.legal_low_level_mask,\n            low_to_high_code=low_to_high_code,\n            legality_engine=legality_engine,\n            metadata=metadata,\n        )\n    payload_by_low_level_code: dict[int, dict[str, Any]] = {}\n    label_by_low_level_code: dict[int, str] = {}\n    for spec, item in zip(materialized_specs, spec_payloads, strict=False):\n        action_code = int(spec.action_code)\n        payload = dict(item.payload)\n        existing_payload = payload_by_low_level_code.get(action_code)\n        if existing_payload is not None:\n            if existing_payload != payload:\n                print(\n                    "[action-payload-collision] "\n                    f"action_code={action_code} "\n                    f"label={spec.label} "\n                    f"kept_payload={existing_payload} "\n                    f"dropped_payload={payload}",\n                    flush=True,\n                )\n            continue\n        payload_by_low_level_code[action_code] = payload\n        label_by_low_level_code[action_code] = str(spec.label)\n    context = DecisionContext(\n        acting_player=acting_player,\n        request_type=request_type,\n        step_index=step_index,\n        full_state=full_state,\n        legal_low_level_codes=encoded_actions.legal_low_level_codes,\n        legal_low_level_specs=tuple(materialized_specs),\n        legal_low_level_mask=encoded_actions.legal_low_level_mask,\n        legal_high_level_codes=encoded_actions.legal_high_level_codes,\n        high_to_low_map=encoded_actions.high_to_low_map,\n        player_view=player_view,\n        full_state_json=full_state_json,\n        request_payload=request_payload,\n        metadata=metadata,\n    )\n    return BuiltDecisionContext(\n        context=context,\n        payload_by_low_level_code=payload_by_low_level_code,\n        label_by_low_level_code=label_by_low_level_code,\n        low_to_high_code=low_to_high_code,\n    )\n\n\ndef _relabel_action_high_levels_by_result(\n    *,\n    acting_player: int,\n    full_state_json: str,\n    full_state: StateSnapshot,\n    legal_low_level_codes: tuple[int, ...],\n    legal_low_level_mask: tuple[bool, ...],\n    low_to_high_code: dict[int, int],\n    legality_engine,\n    metadata: dict[str, Any] | None,\n) -> tuple[Any, dict[int, int]]:\n    from .env import GitcgDecisionEnv\n\n    metadata = metadata or {}\n    matchup = _matchup_from_metadata(metadata)\n    cache_key = _result_relabel_cache_key(\n        acting_player=acting_player,\n        full_state_json=full_state_json,\n        legal_low_level_codes=legal_low_level_codes,\n    )\n    with _RESULT_RELABEL_CACHE_LOCK:\n        cached = _RESULT_RELABEL_CACHE.get(cache_key)\n    if cached is not None:\n        return rebuild_encoded_action_set(\n            legal_low_level_codes=legal_low_level_codes,\n            legal_low_level_mask=legal_low_level_mask,\n            low_to_high_code=cached,\n        ), dict(cached)\n    env = GitcgDecisionEnv(\n        _result_relabel_env_config(),\n        matchup,\n        enable_result_based_action_relabel=False,\n    )\n    codebook = legality_engine.codebook\n    relabeled: dict[int, int] = {}\n    try:\n        for action_code in legal_low_level_codes:\n            spec = codebook.low_spec(int(action_code))\n            # These kinds still have real downstream game consequences, but under the\n            # current ACTION taxonomy their primary high-level label is defined by the\n            # action type itself:\n            # - declare_end -> yield_initiative\n            # - switch_active -> switch_character\n            # - elemental_tuning -> elemental_tuning\n            # We therefore skip the one-step relabel simulation here because the\n            # simulated post-state would not change the chosen high-level bucket.\n            if spec.kind in _DIRECT_ACTION_LABEL_KINDS:\n                key = classify_action_outcome_key(\n                    spec=spec,\n                    pre_state=full_state,\n                    post_state=full_state,\n                    acting_player=acting_player,\n                )\n                relabeled[int(action_code)] = high_level_code_for_key(\n                    codebook,\n                    DecisionType.ACTION,\n                    key,\n                )\n                continue\n            env.reset(state_json=full_state_json)\n            _, step, _ = env.step(ActionChoice(action_code=int(action_code)))\n            key = classify_action_outcome_key(\n                spec=spec,\n                pre_state=full_state,\n                post_state=step.post_state,\n                acting_player=acting_player,\n            )\n            relabeled[int(action_code)] = high_level_code_for_key(\n                codebook,\n                DecisionType.ACTION,\n                key,\n            )\n    except Exception:\n        return rebuild_encoded_action_set(\n            legal_low_level_codes=legal_low_level_codes,\n            legal_low_level_mask=legal_low_level_mask,\n            low_to_high_code=low_to_high_code,\n        ), low_to_high_code\n    finally:\n        env.close()\n    with _RESULT_RELABEL_CACHE_LOCK:\n        if len(_RESULT_RELABEL_CACHE) >= _RESULT_RELABEL_CACHE_LIMIT:\n            oldest_key = next(iter(_RESULT_RELABEL_CACHE))\n            _RESULT_RELABEL_CACHE.pop(oldest_key, None)\n        _RESULT_RELABEL_CACHE[cache_key] = dict(relabeled)\n    return rebuild_encoded_action_set(\n        legal_low_level_codes=legal_low_level_codes,\n        legal_low_level_mask=legal_low_level_mask,\n        low_to_high_code=relabeled,\n    ), relabeled\n\n\ndef _matchup_from_metadata(metadata: dict[str, Any]) -> Matchup:\n    matchup_key = str(metadata.get("matchup", "unknown__vs__unknown"))\n    if "__vs__" not in matchup_key:\n        return Matchup("unknown", "unknown")\n    deck0, deck1 = matchup_key.split("__vs__", maxsplit=1)\n    if not deck0 or not deck1:\n        return Matchup("unknown", "unknown")\n    return Matchup(deck0, deck1)\n\n\ndef _result_relabel_env_config() -> EnvConfig:\n    return EnvConfig(\n        deck_pool=(),\n        record_full_state_json=False,\n        record_player_view=True,\n        draw_penalty=0.0,\n    )\n\n\ndef _result_relabel_cache_key(\n    *,\n    acting_player: int,\n    full_state_json: str,\n    legal_low_level_codes: tuple[int, ...],\n) -> tuple[Any, ...]:\n    digest = hashlib.blake2b(full_state_json.encode("utf-8"), digest_size=16).hexdigest()\n    return (\n        int(acting_player),\n        digest,\n        tuple(int(code) for code in legal_low_level_codes),\n    )\n\n\ndef _choose_active_specs(**kwargs):\n    request = kwargs["request"]\n    acting_player = kwargs["acting_player"]\n    state = kwargs["player_view"] or kwargs["full_state"]\n    slot_by_character_id = {\n        int(character.id): index\n        for index, character in enumerate(state.players[acting_player].characters)\n    }\n    definition_by_character_id = {\n        int(character.id): int(character.definition_id)\n        for character in state.players[acting_player].characters\n    }\n    specs = []\n    for character_id in request.candidate_ids:\n        specs.append(\n            _SpecPayload(\n                spec=LowLevelActionSpec(\n                    action_code=-1,\n                    request_type=DecisionType.CHOOSE_ACTIVE,\n                    kind=OptionKind.CHOOSE_ACTIVE,\n                    label=f"choose_active:{character_id}",\n                    subject_definition_id=int(definition_by_character_id.get(int(character_id), 0)),\n                    choose_active_slot=int(slot_by_character_id.get(int(character_id), -1)),\n                ),\n                payload={"active_character_id": character_id},\n            )\n        )\n    return specs, {\n        "candidate_ids": list(request.candidate_ids),\n        "candidate_definition_ids": [\n            int(definition_by_character_id.get(int(character_id), 0))\n            for character_id in request.candidate_ids\n        ],\n    }\n\n\ndef _select_card_specs(**kwargs):\n    request = kwargs["request"]\n    specs = [\n        _SpecPayload(\n            spec=LowLevelActionSpec(\n                action_code=-1,\n                request_type=DecisionType.SELECT_CARD,\n                kind=OptionKind.SELECT_CARD,\n                label=f"select_card:{definition_id}",\n                subject_definition_id=int(definition_id),\n                select_card_definition_id=int(definition_id),\n            ),\n            payload={"selected_definition_id": definition_id},\n        )\n        for definition_id in request.candidate_definition_ids\n    ]\n    return specs, {\n        "candidate_definition_ids": list(request.candidate_definition_ids),\n    }\n\n\ndef _reroll_specs(**kwargs):\n    acting_player = kwargs["acting_player"]\n    player_view = kwargs["player_view"]\n    if player_view is None:\n        raise ValueError("player_view is required for reroll enumeration")\n    visible_dice = player_view.players[acting_player].dice\n    specs = [\n        _SpecPayload(\n            spec=LowLevelActionSpec(\n                action_code=-1,\n                request_type=DecisionType.REROLL_DICE,\n                kind=OptionKind.REROLL_DICE,\n                label=f"reroll:{\',\'.join(map(str, dice_to_reroll)) or \'none\'}",\n                reroll_dice_mask=_reroll_mask_from_subset(visible_dice, dice_to_reroll),\n            ),\n            payload={"dice_to_reroll": list(dice_to_reroll)},\n        )\n        for dice_to_reroll in _enumerate_multiset_subsets(visible_dice)\n    ]\n    return specs, {"visible_dice": list(visible_dice)}\n\n\ndef _switch_hands_specs(**kwargs):\n    acting_player = kwargs["acting_player"]\n    player_view = kwargs["player_view"]\n    if player_view is None:\n        raise ValueError("player_view is required for switch-hands enumeration")\n    hand_cards = tuple(player_view.players[acting_player].hand_cards)\n    hand_ids = tuple(card.id for card in hand_cards)\n    specs = []\n    for removed_ids in _enumerate_id_subsets(hand_ids):\n        switch_mask = _switch_hand_mask_from_removed_ids(hand_cards, removed_ids)\n        removed_definitions = [\n            int(card.definition_id)\n            for index, card in enumerate(hand_cards)\n            if switch_mask & (1 << index)\n        ]\n        subject_definition_id = removed_definitions[0] if removed_definitions else 0\n        specs.append(\n            _SpecPayload(\n                spec=LowLevelActionSpec(\n                    action_code=-1,\n                    request_type=DecisionType.SWITCH_HANDS,\n                    kind=OptionKind.SWITCH_HANDS,\n                    label=f"switch_hands:{\',\'.join(map(str, removed_ids)) or \'none\'}",\n                    subject_definition_id=int(subject_definition_id),\n                    switch_hand_slot_mask=int(switch_mask),\n                ),\n                payload={"removed_hand_ids": list(removed_ids)},\n            )\n        )\n    return specs, {\n        "hand_ids": list(hand_ids),\n        "hand_definition_ids": [int(card.definition_id) for card in hand_cards],\n    }\n\n\ndef _action_specs(**kwargs):\n    request = kwargs["request"]\n    acting_player = kwargs["acting_player"]\n    player_view = kwargs["player_view"]\n    if player_view is None:\n        raise ValueError("player_view is required for action enumeration")\n    visible_dice = tuple(player_view.players[acting_player].dice)\n    hand_card_definitions = {\n        int(card.id): int(card.definition_id)\n        for card in player_view.players[acting_player].hand_cards\n    }\n    specs: list[_SpecPayload] = []\n    for action_index, action in enumerate(request.action):\n        if getattr(action, "validity", None) != 0:\n            continue\n        kind, label, semantic = _classify_action(action, state=player_view, acting_player=acting_player)\n        semantic = _enrich_action_semantics(\n            kind=kind,\n            semantic=semantic,\n            hand_card_definitions=hand_card_definitions,\n        )\n        auto_selected = tuple(int(d) for d in getattr(action, "auto_selected_dice", ()))\n        payments = (\n            [auto_selected]\n            if auto_selected\n            else _enumerate_action_dice_payments(visible_dice, action.required_cost)\n        )\n        if kind == OptionKind.ACTION_DECLARE_END and not payments:\n            payments = [tuple()]\n        if not payments:\n            continue\n        for used_dice in payments:\n            specs.append(\n                _SpecPayload(\n                    spec=LowLevelActionSpec(\n                        action_code=-1,\n                        request_type=DecisionType.ACTION,\n                        kind=kind,\n                        label=f"{label}:{action_index}:{\',\'.join(map(str, used_dice)) or \'none\'}",\n                        subject_definition_id=int(semantic.get("subject_definition_id", 0)),\n                        target_slots=tuple(semantic.get("target_slots", ())),\n                        used_dice=tuple(used_dice),\n                        auto_selected_dice=auto_selected,\n                        discarded_hand_slot=int(semantic.get("discarded_hand_slot", -1)),\n                        discarded_card_definition_id=int(semantic.get("discarded_card_definition_id", 0)),\n                        target_dice=int(semantic.get("target_dice", 0)),\n                        metadata={\n                            "action_index": int(action_index),\n                            "required_cost": tuple(\n                                (int(req.type), int(req.count))\n                                for req in action.required_cost\n                            ),\n                            "is_fast": bool(getattr(action, "is_fast", False)),\n                        },\n                    ),\n                    payload={\n                        "chosen_action_index": action_index,\n                        "used_dice": list(used_dice),\n                    },\n                )\n            )\n    return specs, {"visible_dice": list(visible_dice), "legal_action_count": len(specs)}\n\n\ndef _classify_action(\n    action: Any,\n    *,\n    state: StateSnapshot,\n    acting_player: int,\n) -> tuple[OptionKind, str, dict[str, Any]]:\n    if action.HasField("use_skill"):\n        value = action.use_skill\n        return (\n            OptionKind.ACTION_USE_SKILL,\n            "use_skill",\n            {\n                "subject_definition_id": int(value.skill_definition_id),\n                "target_slots": _target_slots_from_ids(tuple(int(target) for target in value.target_ids), state=state, acting_player=acting_player),\n            },\n        )\n    if action.HasField("play_card"):\n        value = action.play_card\n        return (\n            OptionKind.ACTION_PLAY_CARD,\n            "play_card",\n            {\n                "subject_definition_id": int(value.card_definition_id),\n                "target_slots": _target_slots_from_ids(tuple(int(target) for target in value.target_ids), state=state, acting_player=acting_player),\n            },\n        )\n    if action.HasField("switch_active"):\n        value = action.switch_active\n        return (\n            OptionKind.ACTION_SWITCH_ACTIVE,\n            "switch_active",\n            {\n                "subject_definition_id": int(value.character_definition_id),\n                "target_slots": _target_slots_for_switch_active(state=state, acting_player=acting_player, character_id=int(value.character_id)),\n            },\n        )\n    if action.HasField("elemental_tuning"):\n        value = action.elemental_tuning\n        return (\n            OptionKind.ACTION_ELEMENTAL_TUNING,\n            "elemental_tuning",\n            {\n                "removed_card_id": int(value.removed_card_id),\n                "target_dice": int(value.target_dice),\n            },\n        )\n    return (\n        OptionKind.ACTION_DECLARE_END,\n        "declare_end",\n        {},\n    )\n\n\ndef _enrich_action_semantics(\n    *,\n    kind: OptionKind,\n    semantic: dict[str, Any],\n    hand_card_definitions: dict[int, int],\n) -> dict[str, Any]:\n    enriched = dict(semantic)\n    if kind == OptionKind.ACTION_ELEMENTAL_TUNING:\n        removed_card_id = int(semantic.get("removed_card_id", 0))\n        removed_card_definition_id = int(hand_card_definitions.get(removed_card_id, 0))\n        if removed_card_definition_id > 0:\n            enriched["subject_definition_id"] = removed_card_definition_id\n            enriched["discarded_card_definition_id"] = removed_card_definition_id\n    return enriched\n\n\ndef _build_target_lookup(state: StateSnapshot) -> dict[int, dict[str, int | bool | str]]:\n    lookup: dict[int, dict[str, int | bool | str]] = {}\n\n    def register(\n        entity_id: int,\n        *,\n        owner: int,\n        kind: str,\n        definition_id: int,\n        public_index: int,\n        is_active: bool = False,\n        defeated: bool = False,\n    ) -> None:\n        lookup[int(entity_id)] = {\n            "owner": owner,\n            "kind": kind,\n            "definition_id": int(definition_id),\n            "public_index": int(public_index),\n            "is_active": bool(is_active),\n            "defeated": bool(defeated),\n        }\n\n    for owner, player in enumerate(state.players):\n        for public_index, character in enumerate(player.characters):\n            register(\n                int(character.id),\n                owner=owner,\n                kind="character",\n                definition_id=int(character.definition_id),\n                public_index=public_index,\n                is_active=bool(character.is_active),\n                defeated=bool(character.defeated),\n            )\n            for entity_index, entity in enumerate(character.entities):\n                register(\n                    int(entity.id),\n                    owner=owner,\n                    kind="character_entity",\n                    definition_id=int(entity.definition_id),\n                    public_index=entity_index,\n                    is_active=bool(character.is_active),\n                )\n        for public_index, entity in enumerate(player.combat_statuses):\n            register(\n                int(entity.id),\n                owner=owner,\n                kind="combat_status",\n                definition_id=int(entity.definition_id),\n                public_index=public_index,\n            )\n        for public_index, entity in enumerate(player.summons):\n            register(\n                int(entity.id),\n                owner=owner,\n                kind="summon",\n                definition_id=int(entity.definition_id),\n                public_index=public_index,\n            )\n        for public_index, entity in enumerate(player.supports):\n            register(\n                int(entity.id),\n                owner=owner,\n                kind="support",\n                definition_id=int(entity.definition_id),\n                public_index=public_index,\n            )\n    return lookup\n\n\ndef _target_slots_from_ids(\n    target_ids: tuple[int, ...],\n    *,\n    state: StateSnapshot,\n    acting_player: int,\n) -> tuple[PublicSlotTarget, ...]:\n    lookup = _build_target_lookup(state)\n    targets: list[PublicSlotTarget] = []\n    for target_id in target_ids:\n        target = lookup.get(int(target_id))\n        if target is None:\n            continue\n        owner = "self" if int(target["owner"]) == int(acting_player) else "opponent"\n        zone = "combat_status" if str(target["kind"]) == "status" else str(target["kind"])\n        targets.append(PublicSlotTarget(owner=owner, zone=zone, index=int(target["public_index"])))\n    return tuple(targets)\n\n\ndef _target_slots_for_switch_active(\n    *,\n    state: StateSnapshot,\n    acting_player: int,\n    character_id: int,\n) -> tuple[PublicSlotTarget, ...]:\n    for index, character in enumerate(state.players[acting_player].characters):\n        if int(character.id) == int(character_id):\n            return (PublicSlotTarget(owner="self", zone="character", index=index),)\n    return ()\n\n\ndef _enumerate_action_dice_payments(\n    visible_dice: tuple[int, ...],\n    required_cost: Any,\n) -> list[tuple[int, ...]]:\n    entries = [(int(req.type), int(req.count)) for req in required_cost]\n    total_count = sum(\n        count for req_type, count in entries if req_type not in (REQ_ENERGY, REQ_LEGEND)\n    )\n    if total_count == 0:\n        return [tuple()]\n    unique: set[tuple[int, ...]] = set()\n    for indexes in combinations(range(len(visible_dice)), total_count):\n        chosen = tuple(sorted(int(visible_dice[index]) for index in indexes))\n        if chosen in unique:\n            continue\n        if _satisfies_cost(chosen, entries):\n            unique.add(chosen)\n    return sorted(unique)\n\n\ndef _satisfies_cost(chosen_dice: tuple[int, ...], entries: list[tuple[int, int]]) -> bool:\n    exact_requirements = [(req_type, count) for req_type, count in entries if req_type in ELEMENTAL_DICE]\n    aligned_count = sum(count for req_type, count in entries if req_type == REQ_ALIGNED)\n    void_count = sum(count for req_type, count in entries if req_type == REQ_VOID)\n    counter = Counter(chosen_dice)\n    counter = _consume_exact(counter, exact_requirements)\n    if counter is None:\n        return False\n    if aligned_count and _consume_aligned(counter, aligned_count) is None:\n        return False\n    return len(chosen_dice) == sum(count for _, count in exact_requirements) + aligned_count + void_count\n\n\ndef _consume_exact(\n    counter: Counter[int],\n    exact_requirements: list[tuple[int, int]],\n) -> Counter[int] | None:\n    current = counter.copy()\n    for req_type, count in exact_requirements:\n        exact_available = min(current[req_type], count)\n        remaining = count - exact_available\n        current[req_type] -= exact_available\n        if current[OMNI_DICE] < remaining:\n            return None\n        current[OMNI_DICE] -= remaining\n    return current\n\n\ndef _consume_aligned(counter: Counter[int], aligned_count: int) -> Counter[int] | None:\n    for die_type in ELEMENTAL_DICE:\n        exact_available = min(counter[die_type], aligned_count)\n        remaining = aligned_count - exact_available\n        if counter[OMNI_DICE] < remaining:\n            continue\n        next_counter = counter.copy()\n        next_counter[die_type] -= exact_available\n        next_counter[OMNI_DICE] -= remaining\n        return next_counter\n    if counter[OMNI_DICE] >= aligned_count:\n        next_counter = counter.copy()\n        next_counter[OMNI_DICE] -= aligned_count\n        return next_counter\n    return None\n\n\ndef _enumerate_multiset_subsets(values: tuple[int, ...]) -> list[tuple[int, ...]]:\n    unique: set[tuple[int, ...]] = set()\n    for subset_size in range(len(values) + 1):\n        for indexes in combinations(range(len(values)), subset_size):\n            unique.add(tuple(sorted(values[index] for index in indexes)))\n    return sorted(unique)\n\n\ndef _enumerate_id_subsets(values: tuple[int, ...]) -> list[tuple[int, ...]]:\n    subsets: list[tuple[int, ...]] = []\n    for subset_size in range(len(values) + 1):\n        for indexes in combinations(range(len(values)), subset_size):\n            subsets.append(tuple(sorted(values[index] for index in indexes)))\n    return subsets\n\n\ndef _switch_hand_mask_from_removed_ids(hand_cards: tuple[Any, ...], removed_ids: tuple[int, ...]) -> int:\n    remaining = list(int(value) for value in removed_ids)\n    mask = 0\n    for index, card in enumerate(hand_cards):\n        card_id = int(getattr(card, "id", 0))\n        if card_id in remaining:\n            mask |= 1 << index\n            remaining.remove(card_id)\n    return mask\n\n\ndef _reroll_mask_from_subset(visible_dice: tuple[int, ...], dice_to_reroll: tuple[int, ...]) -> int:\n    remaining = list(int(value) for value in dice_to_reroll)\n    mask = 0\n    for index, die in enumerate(visible_dice):\n        die = int(die)\n        if die in remaining:\n            mask |= 1 << index\n            remaining.remove(die)\n    return mask\n'
ACTION_HIERARCHY_CONTENT = 'from __future__ import annotations\n\nimport tomllib\nfrom collections import Counter\nfrom dataclasses import dataclass, replace\nfrom functools import lru_cache\nfrom pathlib import Path\nfrom threading import RLock\nfrom typing import Any, Iterable, Sequence\n\nfrom .action_semantic_rules import (\n    active_action_card_groups,\n    active_action_categories,\n    active_action_entity_groups,\n    active_action_priority_order,\n    active_action_thresholds,\n)\nfrom .non_action_semantic_rules import (\n    active_card_function_groups as active_non_action_card_function_groups,\n    active_card_function_priority,\n    active_choose_active_role_groups,\n    active_choose_active_role_priority,\n    active_reroll_character_elements,\n)\nfrom .schema import (\n    ActionTaxonomy,\n    DecisionContext,\n    DecisionType,\n    EncodedLegalActionSet,\n    HighLevelActionSpec,\n    LowLevelActionSpec,\n    OptionKind,\n    PublicSlotTarget,\n    StateSnapshot,\n)\n\n_OWNER_VALUES = ("self", "opponent", "neutral")\n_ZONE_VALUES = (\n    "character",\n    "character_entity",\n    "combat_status",\n    "summon",\n    "support",\n    "hand_card",\n    "pile_card",\n)\n_ACTION_REQUEST_TYPES = (\n    DecisionType.ACTION,\n    DecisionType.CHOOSE_ACTIVE,\n    DecisionType.REROLL_DICE,\n    DecisionType.SELECT_CARD,\n    DecisionType.SWITCH_HANDS,\n)\n\n\ndef default_action_taxonomy_path() -> Path:\n    return Path(__file__).with_name("action_taxonomy.toml")\n\n\n@lru_cache(maxsize=1)\ndef load_action_taxonomy(path: str | Path | None = None) -> ActionTaxonomy:\n    taxonomy_path = Path(path) if path is not None else default_action_taxonomy_path()\n    payload = tomllib.loads(taxonomy_path.read_text(encoding="utf-8"))\n    active = str(payload["active_taxonomy"])\n    active_block = payload[active]\n    request_type_to_categories: dict[str, tuple[str, ...]] = {}\n    for request_name, config in active_block.items():\n        request_type_to_categories[str(request_name)] = tuple(str(value) for value in config.get("categories", ()))\n    return ActionTaxonomy(\n        active_taxonomy=active,\n        request_type_to_categories=request_type_to_categories,\n    )\n\n\n@dataclass(frozen=True)\nclass HierarchicalActionCodebook:\n    taxonomy: ActionTaxonomy\n    low_level_specs: dict[int, LowLevelActionSpec]\n    high_level_specs: dict[int, HighLevelActionSpec]\n    low_key_to_code: dict[tuple[Any, ...], int]\n    high_key_to_code: dict[tuple[str, str], int]\n    next_low_code: int = 0\n\n    def low_spec(self, action_code: int) -> LowLevelActionSpec:\n        return self.low_level_specs[int(action_code)]\n\n    def high_spec(self, high_action_code: int) -> HighLevelActionSpec:\n        return self.high_level_specs[int(high_action_code)]\n\n    def ensure_low_spec(self, spec: LowLevelActionSpec) -> "HierarchicalActionCodebook":\n        semantic_key = _low_level_semantic_key(spec)\n        existing = self.low_key_to_code.get(semantic_key)\n        if existing is not None:\n            return self\n        code = int(self.next_low_code)\n        materialized = replace(spec, action_code=code)\n        low_level_specs = dict(self.low_level_specs)\n        low_level_specs[code] = materialized\n        low_key_to_code = dict(self.low_key_to_code)\n        low_key_to_code[semantic_key] = code\n        return HierarchicalActionCodebook(\n            taxonomy=self.taxonomy,\n            low_level_specs=low_level_specs,\n            high_level_specs=self.high_level_specs,\n            low_key_to_code=low_key_to_code,\n            high_key_to_code=self.high_key_to_code,\n            next_low_code=code + 1,\n        )\n\n    def code_for(self, spec: LowLevelActionSpec) -> int:\n        return int(self.low_key_to_code[_low_level_semantic_key(spec)])\n\n\n@dataclass(frozen=True)\nclass ActionOutcomeFeatures:\n    opponent_frontline_hp_loss: int\n    opponent_backline_hp_loss_total: int\n    opponent_frontline_lethal: bool\n    self_frontline_tank_delta: int\n    self_team_tank_delta: int\n    self_team_hp_gain_count: int\n    self_frontline_energy_delta: int\n    self_burst_ready_delta: int\n    self_hand_count_delta: int\n    self_support_delta: int\n    self_summon_delta: int\n    self_durable_status_delta: int\n    future_damage_asset_delta: int\n\n\nclass ActionLegalityEngine:\n    def __init__(self, codebook: HierarchicalActionCodebook) -> None:\n        self.codebook = codebook\n\n    def encode_legal_actions(\n        self,\n        *,\n        acting_player: int,\n        visible_state: StateSnapshot,\n        legal_specs: Iterable[LowLevelActionSpec],\n    ) -> tuple[EncodedLegalActionSet, tuple[LowLevelActionSpec, ...], dict[int, int]]:\n        low_codes: list[int] = []\n        materialized_specs: list[LowLevelActionSpec] = []\n        low_to_high: dict[int, int] = {}\n        with _DEFAULT_CODEBOOK_LOCK:\n            global _DEFAULT_CODEBOOK\n            mutable_codebook = _DEFAULT_CODEBOOK or build_default_hierarchical_action_codebook()\n            for spec in legal_specs:\n                mutable_codebook = mutable_codebook.ensure_low_spec(spec)\n                action_code = mutable_codebook.code_for(spec)\n                materialized_spec = mutable_codebook.low_spec(action_code)\n                low_codes.append(action_code)\n                materialized_specs.append(materialized_spec)\n                low_to_high[action_code] = high_level_code_for_spec(\n                    mutable_codebook,\n                    materialized_spec,\n                    visible_state=visible_state,\n                    acting_player=acting_player,\n                )\n            _DEFAULT_CODEBOOK = mutable_codebook\n            self.codebook = mutable_codebook\n        unique_high_codes: list[int] = []\n        high_to_low: dict[int, list[int]] = {}\n        for code in low_codes:\n            high_code = int(low_to_high[code])\n            if high_code not in high_to_low:\n                unique_high_codes.append(high_code)\n                high_to_low[high_code] = []\n            high_to_low[high_code].append(int(code))\n        encoded = EncodedLegalActionSet(\n            legal_low_level_codes=tuple(int(code) for code in low_codes),\n            legal_low_level_mask=tuple(True for _ in low_codes),\n            legal_high_level_codes=tuple(int(code) for code in unique_high_codes),\n            high_to_low_map=tuple(\n                (int(high_code), tuple(int(code) for code in codes))\n                for high_code, codes in high_to_low.items()\n            ),\n        )\n        return encoded, tuple(materialized_specs), low_to_high\n\n\ndef build_default_hierarchical_action_codebook() -> HierarchicalActionCodebook:\n    taxonomy = load_action_taxonomy()\n    high_level_specs: dict[int, HighLevelActionSpec] = {}\n    high_key_to_code: dict[tuple[str, str], int] = {}\n    next_high_code = 0\n    for request_type in _ACTION_REQUEST_TYPES:\n        categories = taxonomy.request_type_to_categories.get(request_type.name, ())\n        for key in categories:\n            high_key = (request_type.name, str(key))\n            high_key_to_code[high_key] = next_high_code\n            high_level_specs[next_high_code] = HighLevelActionSpec(\n                high_action_code=next_high_code,\n                request_type=request_type,\n                taxonomy_name=taxonomy.active_taxonomy,\n                key=str(key),\n                label=str(key),\n            )\n            next_high_code += 1\n    return HierarchicalActionCodebook(\n        taxonomy=taxonomy,\n        low_level_specs={},\n        high_level_specs=high_level_specs,\n        low_key_to_code={},\n        high_key_to_code=high_key_to_code,\n        next_low_code=0,\n    )\n\n\n_DEFAULT_CODEBOOK_LOCK = RLock()\n_DEFAULT_CODEBOOK: HierarchicalActionCodebook | None = None\n\n\ndef default_hierarchical_action_codebook() -> HierarchicalActionCodebook:\n    global _DEFAULT_CODEBOOK\n    with _DEFAULT_CODEBOOK_LOCK:\n        if _DEFAULT_CODEBOOK is None:\n            _DEFAULT_CODEBOOK = build_default_hierarchical_action_codebook()\n        return _DEFAULT_CODEBOOK\n\n\ndef set_default_hierarchical_action_codebook(codebook: HierarchicalActionCodebook) -> None:\n    global _DEFAULT_CODEBOOK\n    with _DEFAULT_CODEBOOK_LOCK:\n        _DEFAULT_CODEBOOK = codebook\n\n\ndef build_action_legality_engine() -> ActionLegalityEngine:\n    return ActionLegalityEngine(default_hierarchical_action_codebook())\n\ndef high_level_code_for_spec(\n    codebook: HierarchicalActionCodebook,\n    spec: LowLevelActionSpec,\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> int:\n    key = _high_level_key_for_spec(spec, visible_state=visible_state, acting_player=acting_player)\n    return high_level_code_for_key(codebook, spec.request_type, key)\n\n\ndef high_level_code_for_key(\n    codebook: HierarchicalActionCodebook,\n    request_type: DecisionType,\n    key: str,\n) -> int:\n    high_code = codebook.high_key_to_code.get((request_type.name, str(key)))\n    if high_code is None:\n        categories = codebook.taxonomy.request_type_to_categories.get(request_type.name, ())\n        fallback_key = categories[0] if categories else "fallback"\n        high_code = codebook.high_key_to_code[(request_type.name, fallback_key)]\n    return int(high_code)\n\n\ndef rebuild_encoded_action_set(\n    *,\n    legal_low_level_codes: Sequence[int],\n    legal_low_level_mask: Sequence[bool],\n    low_to_high_code: dict[int, int],\n) -> EncodedLegalActionSet:\n    unique_high_codes: list[int] = []\n    high_to_low: dict[int, list[int]] = {}\n    for action_code in legal_low_level_codes:\n        high_code = int(low_to_high_code[int(action_code)])\n        if high_code not in high_to_low:\n            unique_high_codes.append(high_code)\n            high_to_low[high_code] = []\n        high_to_low[high_code].append(int(action_code))\n    return EncodedLegalActionSet(\n        legal_low_level_codes=tuple(int(code) for code in legal_low_level_codes),\n        legal_low_level_mask=tuple(bool(value) for value in legal_low_level_mask),\n        legal_high_level_codes=tuple(int(code) for code in unique_high_codes),\n        high_to_low_map=tuple(\n            (int(high_code), tuple(int(code) for code in codes))\n            for high_code, codes in high_to_low.items()\n        ),\n    )\n\n\ndef low_level_semantic_key_for_code(action_code: int) -> tuple[Any, ...]:\n    return _low_level_semantic_key(default_hierarchical_action_codebook().low_spec(action_code))\n\n\ndef low_level_spec_for_code(action_code: int) -> LowLevelActionSpec:\n    return default_hierarchical_action_codebook().low_spec(action_code)\n\n\ndef try_low_level_spec_for_code(action_code: int) -> LowLevelActionSpec | None:\n    try:\n        return low_level_spec_for_code(int(action_code))\n    except KeyError:\n        return None\n\n\ndef high_level_spec_for_code(high_action_code: int) -> HighLevelActionSpec:\n    return default_hierarchical_action_codebook().high_spec(high_action_code)\n\n\ndef high_action_vocab_size() -> int:\n    return len(default_hierarchical_action_codebook().high_level_specs)\n\ndef legal_low_level_specs(context: DecisionContext) -> tuple[LowLevelActionSpec, ...]:\n    if context.legal_low_level_specs:\n        return tuple(context.legal_low_level_specs)\n    recovered: list[LowLevelActionSpec] = []\n    for code in context.legal_low_level_codes:\n        spec = try_low_level_spec_for_code(int(code))\n        if spec is not None:\n            recovered.append(spec)\n    return tuple(recovered)\n\n\ndef selected_low_level_code(step) -> int | None:\n    action_code = int(getattr(step.choice, "action_code", -1))\n    if action_code >= 0:\n        return action_code\n    return None\n\n\ndef selected_low_level_spec(step) -> LowLevelActionSpec | None:\n    stored = getattr(step, "chosen_low_level_spec", None)\n    if stored is not None:\n        return stored\n    action_code = selected_low_level_code(step)\n    if action_code is None:\n        return None\n    try:\n        return low_level_spec_for_code(int(action_code))\n    except KeyError:\n        return None\n\n\ndef selected_high_level_code(step) -> int | None:\n    value = getattr(step, "chosen_high_level_code", None)\n    if value is not None:\n        return int(value)\n    if getattr(step, "high_to_low_map", ()):\n        mapping = {int(high): tuple(int(code) for code in low_codes) for high, low_codes in step.high_to_low_map}\n        action_code = selected_low_level_code(step)\n        if action_code is not None:\n            for high_code, low_codes in mapping.items():\n                if int(action_code) in low_codes:\n                    return int(high_code)\n    spec = selected_low_level_spec(step)\n    if spec is None:\n        return None\n    return None\n\n\ndef low_level_kind_for_code(action_code: int) -> OptionKind:\n    return low_level_spec_for_code(int(action_code)).kind\n\ndef try_low_level_kind_for_code(action_code: int) -> OptionKind | None:\n    spec = try_low_level_spec_for_code(int(action_code))\n    return spec.kind if spec is not None else None\n\n\ndef semantic_action_key_for_code(action_code: int) -> tuple[Any, ...]:\n    spec = low_level_spec_for_code(int(action_code))\n    return semantic_action_key_for_spec(spec)\n\ndef try_semantic_action_key_for_code(action_code: int) -> tuple[Any, ...] | None:\n    spec = try_low_level_spec_for_code(int(action_code))\n    if spec is None:\n        return None\n    return semantic_action_key_for_spec(spec)\n\ndef semantic_action_key_for_spec(spec: LowLevelActionSpec) -> tuple[Any, ...]:\n    return (\n        ("request_type", spec.request_type.value),\n        ("kind", spec.kind.value),\n        ("subject_definition_id", int(spec.subject_definition_id)),\n        (\n            "skill_definition_id",\n            int(spec.subject_definition_id) if spec.kind == OptionKind.ACTION_USE_SKILL else 0,\n        ),\n        (\n            "card_definition_id",\n            int(spec.subject_definition_id) if spec.kind == OptionKind.ACTION_PLAY_CARD else 0,\n        ),\n        ("candidate_definition_id", int(spec.select_card_definition_id)),\n        ("removed_card_definition_id", int(spec.discarded_card_definition_id)),\n        (\n            "target_slots",\n            tuple((target.owner, target.zone, int(target.index)) for target in spec.target_slots),\n        ),\n        ("used_dice", tuple(int(value) for value in sorted(spec.used_dice))),\n        ("auto_selected_dice", tuple(int(value) for value in sorted(spec.auto_selected_dice))),\n        ("choose_active_slot", int(spec.choose_active_slot)),\n        ("switch_hand_slot_mask", int(spec.switch_hand_slot_mask)),\n        ("reroll_dice_mask", int(spec.reroll_dice_mask)),\n        ("discarded_hand_slot", int(spec.discarded_hand_slot)),\n        ("target_dice", int(spec.target_dice)),\n    )\n\n\ndef public_spent_dice_for_code(action_code: int) -> int:\n    spec = low_level_spec_for_code(int(action_code))\n    return public_spent_dice_for_spec(spec)\n\n\ndef try_public_spent_dice_for_code(action_code: int) -> int | None:\n    spec = try_low_level_spec_for_code(int(action_code))\n    if spec is None:\n        return None\n    return public_spent_dice_for_spec(spec)\n\n\ndef public_spent_dice_for_spec(spec: LowLevelActionSpec) -> int:\n    if spec.kind == OptionKind.ACTION_ELEMENTAL_TUNING:\n        return 0\n    return len(spec.used_dice)\n\n\ndef match_low_level_code_index(context: DecisionContext, reference_action_code: int) -> int | None:\n    reference_key = semantic_action_key_for_code(int(reference_action_code))\n    specs = legal_low_level_specs(context)\n    if specs:\n        for index, spec in enumerate(specs):\n            candidate_key = semantic_action_key_for_spec(spec)\n            if candidate_key == reference_key:\n                return index\n        return None\n    for index, action_code in enumerate(context.legal_low_level_codes):\n        candidate_key = semantic_action_key_for_code(int(action_code))\n        if candidate_key == reference_key:\n            return index\n    return None\n\n\ndef legal_high_to_low_dict(context: DecisionContext) -> dict[int, tuple[int, ...]]:\n    if context.high_to_low_map:\n        return {int(high): tuple(int(code) for code in low_codes) for high, low_codes in context.high_to_low_map}\n    return {}\n\n\ndef aggregate_high_policy(\n    *,\n    context: DecisionContext,\n    low_level_policy: Sequence[float],\n) -> tuple[float, ...]:\n    high_dim = high_action_vocab_size()\n    aggregated = [0.0] * high_dim\n    high_to_low = legal_high_to_low_dict(context)\n    legal_codes = tuple(int(code) for code in context.legal_low_level_codes)\n    if len(low_level_policy) != len(legal_codes):\n        print(\n            "[aggregate-high-policy] "\n            f"length_mismatch policy={len(low_level_policy)} legal={len(legal_codes)}",\n            flush=True,\n        )\n    usable = min(len(low_level_policy), len(legal_codes))\n    probability_by_code = {\n        int(legal_codes[index]): float(low_level_policy[index])\n        for index in range(usable)\n    }\n    for high_code, low_codes in high_to_low.items():\n        aggregated[int(high_code)] = sum(probability_by_code.get(int(code), 0.0) for code in low_codes)\n    total = sum(aggregated)\n    if total > 0:\n        aggregated = [value / total for value in aggregated]\n    return tuple(aggregated)\n\n\ndef _low_level_semantic_key(spec: LowLevelActionSpec) -> tuple[Any, ...]:\n    return (\n        spec.request_type.value,\n        spec.kind.value,\n        int(spec.subject_definition_id),\n        tuple((target.owner, target.zone, int(target.index)) for target in spec.target_slots),\n        tuple(int(value) for value in sorted(spec.used_dice)),\n        tuple(int(value) for value in sorted(spec.auto_selected_dice)),\n        int(spec.choose_active_slot),\n        int(spec.select_card_definition_id),\n        int(spec.switch_hand_slot_mask),\n        int(spec.reroll_dice_mask),\n        int(spec.discarded_hand_slot),\n        int(spec.discarded_card_definition_id),\n        int(spec.target_dice),\n    )\n\ndef _target_slots_from_metadata(\n    metadata: dict[str, Any],\n    *,\n    acting_player: int,\n) -> tuple[PublicSlotTarget, ...]:\n    owner_ids = tuple(int(value) for value in metadata.get("target_owner_ids", ()))\n    kinds = tuple(str(value) for value in metadata.get("target_kinds", ()))\n    public_indices = tuple(int(value) for value in metadata.get("target_public_indices", ()))\n    targets: list[PublicSlotTarget] = []\n    for owner_id, kind, public_index in zip(owner_ids, kinds, public_indices):\n        owner = "self" if int(owner_id) == int(acting_player) else "opponent"\n        zone = "combat_status" if kind == "status" else str(kind)\n        targets.append(PublicSlotTarget(owner=owner, zone=zone, index=int(public_index)))\n    return tuple(targets)\n\n\ndef _choose_active_slot(\n    metadata: dict[str, Any],\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> int:\n    candidate_definition_id = int(metadata.get("candidate_definition_id", 0))\n    for index, character in enumerate(visible_state.players[acting_player].characters):\n        if int(character.definition_id) == candidate_definition_id:\n            return index\n    return -1\n\n\ndef _discarded_hand_slot(\n    metadata: dict[str, Any],\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> int:\n    removed_card_definition_id = int(metadata.get("removed_card_definition_id", 0))\n    if removed_card_definition_id <= 0:\n        return -1\n    for index, card in enumerate(visible_state.players[acting_player].hand_cards):\n        if int(card.definition_id) == removed_card_definition_id:\n            return index\n    return -1\n\n\ndef _switch_hand_slot_mask(\n    metadata: dict[str, Any],\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> int:\n    removed_definitions = [int(value) for value in metadata.get("removed_hand_definition_ids", ())]\n    if not removed_definitions:\n        return 0\n    remaining = list(removed_definitions)\n    mask = 0\n    for index, card in enumerate(visible_state.players[acting_player].hand_cards):\n        definition_id = int(card.definition_id)\n        if definition_id in remaining:\n            mask |= 1 << index\n            remaining.remove(definition_id)\n    return mask\n\n\ndef _reroll_dice_mask(\n    metadata: dict[str, Any],\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> int:\n    dice_to_reroll = [int(value) for value in metadata.get("dice_to_reroll", ())]\n    if not dice_to_reroll:\n        return 0\n    remaining = list(dice_to_reroll)\n    mask = 0\n    for index, die in enumerate(visible_state.players[acting_player].dice):\n        die = int(die)\n        if die in remaining:\n            mask |= 1 << index\n            remaining.remove(die)\n    return mask\n\n\ndef _high_level_key_for_spec(\n    spec: LowLevelActionSpec,\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> str:\n    if spec.request_type == DecisionType.ACTION:\n        return _provisional_action_high_level_key(\n            spec,\n            visible_state=visible_state,\n            acting_player=acting_player,\n        )\n    if spec.request_type == DecisionType.REROLL_DICE:\n        return _reroll_high_level_key(spec, visible_state=visible_state, acting_player=acting_player)\n    if spec.request_type == DecisionType.CHOOSE_ACTIVE:\n        return _choose_active_high_level_key(spec, visible_state=visible_state, acting_player=acting_player)\n    if spec.request_type == DecisionType.SELECT_CARD:\n        return _select_card_high_level_key(spec)\n    if spec.request_type == DecisionType.SWITCH_HANDS:\n        return _switch_hands_high_level_key(spec, visible_state=visible_state, acting_player=acting_player)\n    return codebook_default_high_key(spec.request_type)\n\n\ndef classify_action_outcome_key(\n    *,\n    spec: LowLevelActionSpec,\n    pre_state: StateSnapshot,\n    post_state: StateSnapshot,\n    acting_player: int,\n) -> str:\n    if spec.kind == OptionKind.ACTION_ELEMENTAL_TUNING:\n        return "elemental_tuning"\n    if spec.kind == OptionKind.ACTION_SWITCH_ACTIVE:\n        return "switch_character"\n    if spec.kind == OptionKind.ACTION_DECLARE_END:\n        return "yield_initiative"\n    features = action_outcome_features(\n        pre_state=pre_state,\n        post_state=post_state,\n        acting_player=acting_player,\n    )\n    return _classify_action_from_features(spec=spec, features=features)\n\n\ndef action_outcome_features(\n    *,\n    pre_state: StateSnapshot,\n    post_state: StateSnapshot,\n    acting_player: int,\n) -> ActionOutcomeFeatures:\n    opponent_player = 1 - int(acting_player)\n    pre_self = pre_state.players[acting_player]\n    post_self = post_state.players[acting_player]\n    pre_opponent = pre_state.players[opponent_player]\n    post_opponent = post_state.players[opponent_player]\n    pre_self_active_index = _active_character_index(pre_self)\n    post_self_active_index = _active_character_index(post_self)\n    pre_opp_active_index = _active_character_index(pre_opponent)\n    post_opp_active_index = _active_character_index(post_opponent)\n    pre_frontline = _character_at(pre_opponent, pre_opp_active_index)\n    post_frontline = _character_at(post_opponent, post_opp_active_index)\n    pre_self_frontline = _character_at(pre_self, pre_self_active_index)\n    post_self_frontline = _character_at(post_self, post_self_active_index)\n    pre_frontline_hp = int(pre_frontline.health) if pre_frontline is not None else 0\n    post_frontline_hp = int(post_frontline.health) if post_frontline is not None else 0\n    opponent_frontline_hp_loss = max(0, pre_frontline_hp - post_frontline_hp)\n    opponent_backline_hp_loss_total = _backline_hp_loss(\n        pre_player=pre_opponent,\n        post_player=post_opponent,\n        active_index=pre_opp_active_index,\n    )\n    opponent_frontline_lethal = bool(\n        pre_frontline is not None\n        and not bool(pre_frontline.defeated)\n        and post_frontline is not None\n        and bool(post_frontline.defeated)\n    )\n    self_frontline_tank_delta = _player_frontline_tankiness(post_self) - _player_frontline_tankiness(pre_self)\n    self_team_tank_delta = _player_team_tankiness(post_self) - _player_team_tankiness(pre_self)\n    self_team_hp_gain_count = _team_hp_gain_count(pre_self, post_self)\n    self_frontline_energy_delta = _frontline_energy(post_self_frontline) - _frontline_energy(pre_self_frontline)\n    self_burst_ready_delta = _burst_ready_count(post_self) - _burst_ready_count(pre_self)\n    self_hand_count_delta = len(post_self.hand_cards) - len(pre_self.hand_cards)\n    self_support_delta = len(post_self.supports) - len(pre_self.supports)\n    self_summon_delta = len(post_self.summons) - len(pre_self.summons)\n    self_durable_status_delta = _durable_status_count(post_self) - _durable_status_count(pre_self)\n    future_damage_asset_delta = _future_damage_asset_score(post_self) - _future_damage_asset_score(pre_self)\n    return ActionOutcomeFeatures(\n        opponent_frontline_hp_loss=int(opponent_frontline_hp_loss),\n        opponent_backline_hp_loss_total=int(opponent_backline_hp_loss_total),\n        opponent_frontline_lethal=bool(opponent_frontline_lethal),\n        self_frontline_tank_delta=int(self_frontline_tank_delta),\n        self_team_tank_delta=int(self_team_tank_delta),\n        self_team_hp_gain_count=int(self_team_hp_gain_count),\n        self_frontline_energy_delta=int(self_frontline_energy_delta),\n        self_burst_ready_delta=int(self_burst_ready_delta),\n        self_hand_count_delta=int(self_hand_count_delta),\n        self_support_delta=int(self_support_delta),\n        self_summon_delta=int(self_summon_delta),\n        self_durable_status_delta=int(self_durable_status_delta),\n        future_damage_asset_delta=int(future_damage_asset_delta),\n    )\n\n\ndef _provisional_action_high_level_key(\n    spec: LowLevelActionSpec,\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> str:\n    categories = set(active_action_categories())\n    card_groups = active_action_card_groups()\n    if spec.kind == OptionKind.ACTION_ELEMENTAL_TUNING and "elemental_tuning" in categories:\n        return "elemental_tuning"\n    if spec.kind == OptionKind.ACTION_SWITCH_ACTIVE and "switch_character" in categories:\n        return "switch_character"\n    if spec.kind == OptionKind.ACTION_DECLARE_END and "yield_initiative" in categories:\n        return "yield_initiative"\n    if spec.kind == OptionKind.ACTION_USE_SKILL:\n        if _targets_opponent_frontline(spec):\n            return "chip_frontline_hp"\n        if _targets_opponent_backline(spec):\n            return "chip_backline_hp"\n        if _targets_self_character(spec, acting_player=acting_player):\n            return "fortify_frontline"\n        return "burst_setup"\n    if spec.kind == OptionKind.ACTION_PLAY_CARD:\n        subject_definition_id = int(spec.subject_definition_id)\n        if subject_definition_id in card_groups.get("cycle_card_ids", frozenset()):\n            return "cycle_for_cards"\n        if subject_definition_id in card_groups.get("engine_card_ids", frozenset()):\n            return "invest_engine_card"\n        if subject_definition_id in card_groups.get("delayed_damage_card_ids", frozenset()):\n            return "invest_delayed_damage"\n        if subject_definition_id in card_groups.get("tech_card_ids", frozenset()):\n            return "invest_tech"\n        if _targets_self_character(spec, acting_player=acting_player):\n            return "fortify_frontline"\n    return "other_action"\n\n\ndef _classify_action_from_features(\n    *,\n    spec: LowLevelActionSpec,\n    features: ActionOutcomeFeatures,\n) -> str:\n    thresholds = active_action_thresholds()\n    card_groups = active_action_card_groups()\n    priority_order = active_action_priority_order()\n    subject_definition_id = int(spec.subject_definition_id)\n    for key in priority_order:\n        if key == "force_frontline_lethal" and features.opponent_frontline_lethal:\n            return key\n        if key == "chip_frontline_hp" and features.opponent_frontline_hp_loss >= int(thresholds["min_frontline_hp_loss"]):\n            return key\n        if key == "chip_backline_hp" and features.opponent_backline_hp_loss_total >= int(thresholds["min_backline_hp_loss"]):\n            return key\n        if key == "fortify_team":\n            if (\n                features.self_team_tank_delta >= int(thresholds["min_team_tank_gain"])\n                and features.self_team_hp_gain_count >= int(thresholds["min_team_hp_gain_count"])\n            ):\n                return key\n        if key == "fortify_frontline" and features.self_frontline_tank_delta >= int(thresholds["min_frontline_tank_gain"]):\n            return key\n        if key == "switch_character" and spec.kind == OptionKind.ACTION_SWITCH_ACTIVE:\n            return key\n        if key == "cycle_for_cards":\n            if (\n                features.self_hand_count_delta >= int(thresholds["min_hand_count_gain"])\n                or subject_definition_id in card_groups.get("cycle_card_ids", frozenset())\n            ):\n                return key\n        if key == "burst_setup":\n            if (\n                features.self_frontline_energy_delta >= int(thresholds["min_frontline_energy_gain"])\n                or features.self_burst_ready_delta >= int(thresholds["min_burst_ready_gain"])\n                or subject_definition_id in card_groups.get("burst_setup_card_ids", frozenset())\n            ):\n                return key\n        if key == "invest_delayed_damage":\n            if (\n                features.future_damage_asset_delta >= int(thresholds["min_future_damage_asset_gain"])\n                or subject_definition_id in card_groups.get("delayed_damage_card_ids", frozenset())\n            ):\n                return key\n        if key == "invest_engine_card" and subject_definition_id in card_groups.get("engine_card_ids", frozenset()):\n            return key\n        if key == "invest_tech":\n            if (\n                subject_definition_id in card_groups.get("tech_card_ids", frozenset())\n                or features.self_support_delta >= int(thresholds["min_support_gain"])\n                or features.self_durable_status_delta >= int(thresholds["min_durable_status_gain"])\n            ):\n                return key\n        if key == "elemental_tuning" and spec.kind == OptionKind.ACTION_ELEMENTAL_TUNING:\n            return key\n        if key == "yield_initiative" and spec.kind == OptionKind.ACTION_DECLARE_END:\n            return key\n    return "other_action"\n\n\ndef _reroll_high_level_key(\n    spec: LowLevelActionSpec,\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> str:\n    if int(spec.reroll_dice_mask) == 0:\n        return "keep_all"\n    player = visible_state.players[acting_player]\n    visible_dice = tuple(int(value) for value in player.dice)\n    if not visible_dice:\n        return "keep_all"\n    rerolled = [\n        die\n        for index, die in enumerate(visible_dice)\n        if int(spec.reroll_dice_mask) & (1 << index)\n    ]\n    kept = [\n        die\n        for index, die in enumerate(visible_dice)\n        if not (int(spec.reroll_dice_mask) & (1 << index))\n    ]\n    active_color, backline_colors = _team_color_profile(visible_state=visible_state, acting_player=acting_player)\n    team_colors = {color for color in (active_color, *backline_colors) if int(color) > 0}\n    kept_counts = Counter(int(die) for die in kept)\n    rerolled_counts = Counter(int(die) for die in rerolled)\n    active_kept = int(kept_counts.get(int(active_color), 0)) if active_color > 0 else 0\n    active_rerolled = int(rerolled_counts.get(int(active_color), 0)) if active_color > 0 else 0\n    backline_pairs = [\n        (\n            int(kept_counts.get(int(color), 0)),\n            int(rerolled_counts.get(int(color), 0)),\n        )\n        for color in backline_colors\n    ]\n    off_kept = sum(\n        int(count)\n        for die, count in kept_counts.items()\n        if int(die) not in team_colors\n    )\n    off_rerolled = sum(\n        int(count)\n        for die, count in rerolled_counts.items()\n        if int(die) not in team_colors\n    )\n    candidates = (\n        ("keep_active_and_two_backline", "keep", True, 2),\n        ("keep_active_and_one_backline", "keep", True, 1),\n        ("keep_active_only", "keep", True, 0),\n        ("keep_two_backline", "keep", False, 2),\n        ("keep_one_backline", "keep", False, 1),\n        ("reroll_active_and_two_backline", "reroll", True, 2),\n        ("reroll_active_and_one_backline", "reroll", True, 1),\n        ("reroll_active_only", "reroll", True, 0),\n        ("reroll_two_backline", "reroll", False, 2),\n        ("reroll_one_backline", "reroll", False, 1),\n    )\n    best_label = "keep_all"\n    best_score: float | None = None\n    for label, family, include_active, backline_target_count in candidates:\n        score = 0.0\n        if active_color > 0:\n            score += _alignment_score(\n                target_keep=(include_active if family == "keep" else not include_active),\n                kept=active_kept,\n                rerolled=active_rerolled,\n            )\n        selected_backline = min(int(backline_target_count), len(backline_pairs))\n        if family == "keep":\n            deltas = [\n                _alignment_score(target_keep=True, kept=kept_count, rerolled=rerolled_count)\n                - _alignment_score(target_keep=False, kept=kept_count, rerolled=rerolled_count)\n                for kept_count, rerolled_count in backline_pairs\n            ]\n            chosen = set(sorted(range(len(deltas)), key=lambda index: deltas[index], reverse=True)[:selected_backline])\n            for index, (kept_count, rerolled_count) in enumerate(backline_pairs):\n                score += _alignment_score(\n                    target_keep=index in chosen,\n                    kept=kept_count,\n                    rerolled=rerolled_count,\n                )\n            score += _alignment_score(target_keep=False, kept=off_kept, rerolled=off_rerolled) * 0.5\n        else:\n            deltas = [\n                _alignment_score(target_keep=False, kept=kept_count, rerolled=rerolled_count)\n                - _alignment_score(target_keep=True, kept=kept_count, rerolled=rerolled_count)\n                for kept_count, rerolled_count in backline_pairs\n            ]\n            chosen = set(sorted(range(len(deltas)), key=lambda index: deltas[index], reverse=True)[:selected_backline])\n            for index, (kept_count, rerolled_count) in enumerate(backline_pairs):\n                score += _alignment_score(\n                    target_keep=index not in chosen,\n                    kept=kept_count,\n                    rerolled=rerolled_count,\n                )\n            score += _alignment_score(target_keep=True, kept=off_kept, rerolled=off_rerolled) * 0.5\n        if best_score is None or score > best_score:\n            best_label = label\n            best_score = score\n    return str(best_label)\n\n\ndef _choose_active_high_level_key(\n    spec: LowLevelActionSpec,\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> str:\n    slot = int(spec.choose_active_slot)\n    if not (0 <= slot < len(visible_state.players[acting_player].characters)):\n        return "choose_other"\n    definition_id = int(visible_state.players[acting_player].characters[slot].definition_id)\n    role_groups = active_choose_active_role_groups()\n    for role in active_choose_active_role_priority():\n        if definition_id in role_groups.get(role, frozenset()):\n            return f"choose_{role}"\n    return "choose_other"\n\n\ndef _select_card_high_level_key(spec: LowLevelActionSpec) -> str:\n    definition_id = int(spec.select_card_definition_id or spec.subject_definition_id)\n    group = _card_function_group_for_definition_id(definition_id)\n    if group is None:\n        return "select_other"\n    if group == "core":\n        return "select_core"\n    return f"select_{group}"\n\n\ndef _switch_hands_high_level_key(\n    spec: LowLevelActionSpec,\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> str:\n    removed_definitions = _removed_hand_definition_ids(\n        spec=spec,\n        visible_state=visible_state,\n        acting_player=acting_player,\n    )\n    if not removed_definitions:\n        return "switch_keep_all"\n    group_counts: Counter[str] = Counter()\n    unknown_count = 0\n    for definition_id in removed_definitions:\n        group = _card_function_group_for_definition_id(int(definition_id))\n        if group is None:\n            unknown_count += 1\n            continue\n        group_counts[group] += 1\n    if not group_counts:\n        return "switch_other"\n    top_group, top_count = max(\n        group_counts.items(),\n        key=lambda item: (int(item[1]), -_card_function_priority_index(item[0])),\n    )\n    total_count = sum(group_counts.values()) + int(unknown_count)\n    if total_count == int(top_count):\n        if top_group == "core":\n            return "switch_core"\n        return f"switch_{top_group}"\n    return "switch_mixed"\n\n\ndef _removed_hand_definition_ids(\n    *,\n    spec: LowLevelActionSpec,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> tuple[int, ...]:\n    removed: list[int] = []\n    for index, card in enumerate(visible_state.players[acting_player].hand_cards):\n        if int(spec.switch_hand_slot_mask) & (1 << index):\n            removed.append(int(card.definition_id))\n    return tuple(removed)\n\n\ndef _card_function_group_for_definition_id(definition_id: int) -> str | None:\n    groups = active_non_action_card_function_groups()\n    for group in active_card_function_priority():\n        if int(definition_id) in groups.get(group, frozenset()):\n            return str(group)\n    return None\n\n\ndef _card_function_priority_index(group: str) -> int:\n    order = active_card_function_priority()\n    try:\n        return int(order.index(str(group)))\n    except ValueError:\n        return len(order)\n\n\ndef _team_color_profile(\n    *,\n    visible_state: StateSnapshot,\n    acting_player: int,\n) -> tuple[int, tuple[int, ...]]:\n    element_map = active_reroll_character_elements()\n    player = visible_state.players[acting_player]\n    active_index = _active_character_index(player)\n    active_color = int(element_map.get(int(player.characters[active_index].definition_id), 0))\n    backline_colors: list[int] = []\n    seen = {active_color} if active_color > 0 else set()\n    for index, character in enumerate(player.characters):\n        if int(index) == int(active_index):\n            continue\n        color = int(element_map.get(int(character.definition_id), 0))\n        if color <= 0 or color in seen:\n            continue\n        seen.add(color)\n        backline_colors.append(color)\n    return active_color, tuple(backline_colors)\n\n\ndef _alignment_score(*, target_keep: bool, kept: int, rerolled: int) -> float:\n    if target_keep:\n        return float(int(kept) - int(rerolled))\n    return float(int(rerolled) - int(kept))\n\n\ndef _targets_opponent_frontline(spec: LowLevelActionSpec) -> bool:\n    return any(\n        target.owner == "opponent" and target.zone == "character" and int(target.index) == 0\n        for target in spec.target_slots\n    )\n\n\ndef _targets_opponent_backline(spec: LowLevelActionSpec) -> bool:\n    return any(\n        target.owner == "opponent" and target.zone == "character" and int(target.index) > 0\n        for target in spec.target_slots\n    )\n\n\ndef _targets_self_character(spec: LowLevelActionSpec, *, acting_player: int) -> bool:\n    del acting_player\n    return any(target.owner == "self" and target.zone == "character" for target in spec.target_slots)\n\n\ndef _active_character_index(player) -> int:\n    for index, character in enumerate(player.characters):\n        if bool(character.is_active):\n            return int(index)\n    return 0\n\n\ndef _character_at(player, index: int):\n    if 0 <= int(index) < len(player.characters):\n        return player.characters[int(index)]\n    return None\n\n\ndef _frontline_energy(character) -> int:\n    if character is None:\n        return 0\n    return int(character.energy)\n\n\ndef _burst_ready_count(player) -> int:\n    return sum(\n        1\n        for character in player.characters\n        if int(character.energy) >= int(character.max_energy)\n    )\n\n\ndef _backline_hp_loss(*, pre_player, post_player, active_index: int) -> int:\n    loss = 0\n    for index, (pre_character, post_character) in enumerate(zip(pre_player.characters, post_player.characters, strict=False)):\n        if int(index) == int(active_index):\n            continue\n        loss += max(0, int(pre_character.health) - int(post_character.health))\n    return int(loss)\n\n\ndef _player_frontline_tankiness(player) -> int:\n    active_index = _active_character_index(player)\n    character = _character_at(player, active_index)\n    if character is None:\n        return 0\n    defensive_entity_ids = active_action_entity_groups().get("defensive_entity_definition_ids", frozenset())\n    value = int(character.health)\n    value += _entity_bonus(tuple(character.entities), definition_ids=defensive_entity_ids)\n    value += _entity_bonus(player.combat_statuses, definition_ids=defensive_entity_ids)\n    return int(value)\n\n\ndef _player_team_tankiness(player) -> int:\n    defensive_entity_ids = active_action_entity_groups().get("defensive_entity_definition_ids", frozenset())\n    value = sum(int(character.health) for character in player.characters)\n    value += sum(_entity_bonus(tuple(character.entities), definition_ids=defensive_entity_ids) for character in player.characters)\n    value += _entity_bonus(player.combat_statuses, definition_ids=defensive_entity_ids)\n    value += _entity_bonus(player.supports, definition_ids=defensive_entity_ids)\n    return int(value)\n\n\ndef _team_hp_gain_count(pre_player, post_player) -> int:\n    count = 0\n    for pre_character, post_character in zip(pre_player.characters, post_player.characters, strict=False):\n        if int(post_character.health) > int(pre_character.health):\n            count += 1\n    return int(count)\n\n\ndef _durable_status_count(player) -> int:\n    return int(len(player.combat_statuses) + len(player.supports) + sum(len(character.entities) for character in player.characters))\n\n\ndef _future_damage_asset_score(player) -> int:\n    offensive_entity_ids = active_action_entity_groups().get("offensive_entity_definition_ids", frozenset())\n    value = len(player.summons)\n    value += _entity_bonus(player.combat_statuses, definition_ids=offensive_entity_ids)\n    value += sum(_entity_bonus(tuple(character.entities), definition_ids=offensive_entity_ids) for character in player.characters)\n    return int(value)\n\n\ndef _entity_bonus(entities: Sequence[Any], *, definition_ids: frozenset[int]) -> int:\n    if not definition_ids:\n        return 0\n    bonus = 0\n    for entity in entities:\n        if int(entity.definition_id) not in definition_ids:\n            continue\n        variables = getattr(entity, "variables", {})\n        if not variables:\n            bonus += 1\n            continue\n        bonus += max(1, sum(max(0, int(value)) for value in variables.values()))\n    return int(bonus)\n\n\ndef codebook_default_high_key(request_type: DecisionType) -> str:\n    categories = load_action_taxonomy().request_type_to_categories.get(request_type.name, ())\n    return categories[0] if categories else "fallback"\n\n\ndef _bit_count(mask: int) -> int:\n    return int(mask).bit_count()\n'
LOOKAHEAD_SEARCH_CONTENT = 'from __future__ import annotations\n\nimport math\nimport os\nimport time\nfrom dataclasses import dataclass, replace\nfrom typing import Sequence\n\nimport torch\n\nfrom .action_hierarchy import (\n    match_low_level_code_index,\n    semantic_action_key_for_code,\n    try_low_level_kind_for_code,\n)\nfrom .decks import SMALL_DECK_MATCHUPS\nfrom .env import GitcgDecisionEnv\nfrom .ppo_features import TokenObservationEncoder\nfrom .ppo_model import PpoTransformerPolicy, masked_log_softmax\nfrom .schema import ActionChoice, DecisionContext, EnvConfig, EpisodeRecord, Matchup, TrajectoryStep\n\n\n@dataclass(frozen=True)\nclass LookaheadSearchConfig:\n    enabled: bool = True\n    round_threshold: int = 6\n    legal_option_threshold: int = 6\n    root_top_k: int = 8\n    depth: int = 3\n    policy_temperature: float = 0.75\n    policy_distill_coef: float = 0.20\n    value_distill_coef: float = 0.10\n    max_states_per_episode: int = 24\n    # episode: only per-episode summary logs (default)\n    # state: add per-state start/done logs\n    # root: add per-root summary logs\n    # option: full detailed per-option logs\n    trace_level: str = "episode"\n\n\n@dataclass(frozen=True)\nclass SearchTeacherTarget:\n    policy_target: tuple[float, ...]\n    action_semantic_keys: tuple[str, ...]\n    value_target: float\n    weight: float\n\n\n_MATCHUP_BY_KEY = {matchup.key: matchup for matchup in SMALL_DECK_MATCHUPS}\n\n\n_TRACE_LEVEL_ORDER = {"episode": 0, "state": 1, "root": 2, "option": 3}\n\n\ndef _normalized_trace_level(config: LookaheadSearchConfig) -> str:\n    value = os.environ.get("SEARCH_TEACHER_TRACE_LEVEL", config.trace_level)\n    level = str(value).strip().lower()\n    return level if level in _TRACE_LEVEL_ORDER else "episode"\n\n\ndef _trace_enabled(config: LookaheadSearchConfig, level: str) -> bool:\n    current = _TRACE_LEVEL_ORDER[_normalized_trace_level(config)]\n    wanted = _TRACE_LEVEL_ORDER.get(str(level).strip().lower(), 0)\n    return current >= wanted\n\n\ndef annotate_episodes_with_search_targets(\n    episodes: Sequence[EpisodeRecord],\n    *,\n    model: PpoTransformerPolicy,\n    encoder: TokenObservationEncoder,\n    device: torch.device,\n    env_config: EnvConfig,\n    config: LookaheadSearchConfig,\n) -> tuple[EpisodeRecord, ...]:\n    # Training-only full-information teacher path. Runtime acting must not call\n    # this module as its search implementation.\n    if not config.enabled:\n        return tuple(episodes)\n    started_at = time.perf_counter()\n    total_episodes = len(episodes)\n    print(\n        (\n            "[search-teacher] start "\n            f"episodes={total_episodes} "\n            f"root_top_k={config.root_top_k} depth={config.depth} "\n            f"max_states_per_episode={config.max_states_per_episode} "\n            f"round_threshold={config.round_threshold} "\n            f"legal_option_threshold={config.legal_option_threshold} "\n            f"trace_level={_normalized_trace_level(config)}"\n        ),\n        flush=True,\n    )\n    annotated: list[EpisodeRecord] = []\n    for episode_index, episode in enumerate(episodes, start=1):\n        episode_started_at = time.perf_counter()\n        if _trace_enabled(config, "state"):\n            print(\n                (\n                    "[search-teacher-episode] "\n                    f"{episode_index}/{total_episodes} "\n                    f"matchup={episode.matchup} seed={episode.seed} steps={len(episode.steps)}"\n                ),\n                flush=True,\n            )\n        annotated_episode = _annotate_episode(\n            episode,\n            model=model,\n            encoder=encoder,\n            device=device,\n            env_config=env_config,\n            config=config,\n            episode_index=episode_index,\n            episode_count=total_episodes,\n        )\n        annotated.append(annotated_episode)\n        target_count = sum(\n            1\n            for step in annotated_episode.steps\n            if float(step.metadata.get("search_teacher_weight", 0.0)) > 0.0\n        )\n        if _trace_enabled(config, "state"):\n            print(\n                (\n                    "[search-teacher-episode-done] "\n                    f"{episode_index}/{total_episodes} "\n                    f"targets={target_count} elapsed_s={time.perf_counter() - episode_started_at:.2f}"\n                ),\n                flush=True,\n            )\n    print(\n        f"[search-teacher] done episodes={total_episodes} elapsed_s={time.perf_counter() - started_at:.2f}",\n        flush=True,\n    )\n    return tuple(annotated)\n\n\ndef _annotate_episode(\n    episode: EpisodeRecord,\n    *,\n    model: PpoTransformerPolicy,\n    encoder: TokenObservationEncoder,\n    device: torch.device,\n    env_config: EnvConfig,\n    config: LookaheadSearchConfig,\n    episode_index: int | None = None,\n    episode_count: int | None = None,\n) -> EpisodeRecord:\n    matchup = _MATCHUP_BY_KEY.get(episode.matchup)\n    if matchup is None:\n        print(\n            f"[search-teacher-episode-skip] matchup_unavailable matchup={episode.matchup}",\n            flush=True,\n        )\n        return episode\n    remaining_budget = int(config.max_states_per_episode)\n    steps: list[TrajectoryStep] = []\n    considered_states = 0\n    annotated_states = 0\n    total_steps = len(episode.steps)\n    episode_label = (\n        f"{episode_index}/{episode_count}"\n        if episode_index is not None and episode_count is not None\n        else "?"\n    )\n    for step_index, step in enumerate(episode.steps, start=1):\n        target: SearchTeacherTarget | None = None\n        if float(step.metadata.get("search_teacher_weight", 0.0)) > 0.0:\n            steps.append(step)\n            continue\n        if remaining_budget > 0 and _is_search_state(step, config=config):\n            considered_states += 1\n            trace_prefix = (\n                f"episode={episode_label} step={step_index}/{total_steps} "\n                f"round={step.pre_state.round_number} legal={len(step.legal_low_level_codes)} "\n                f"budget_left={remaining_budget}"\n            )\n            state_started_at = time.perf_counter()\n            if _trace_enabled(config, "state"):\n                print(f"[search-teacher-state] {trace_prefix}", flush=True)\n            target = _search_teacher_target(\n                step=step,\n                matchup=matchup,\n                model=model,\n                encoder=encoder,\n                device=device,\n                env_config=env_config,\n                config=config,\n                seed=episode.seed,\n                trace_prefix=(trace_prefix if _trace_enabled(config, "root") else None),\n            )\n            state_elapsed_ms = (time.perf_counter() - state_started_at) * 1000.0\n            if target is not None:\n                remaining_budget -= 1\n                annotated_states += 1\n            if _trace_enabled(config, "state"):\n                print(\n                    (\n                        "[search-teacher-state-done] "\n                        f"{trace_prefix} "\n                        f"status={\'hit\' if target is not None else \'miss\'} "\n                        f"elapsed_ms={state_elapsed_ms:.1f} "\n                        f"remaining_budget={remaining_budget}"\n                    ),\n                    flush=True,\n                )\n        if target is None:\n            steps.append(step)\n            continue\n        metadata = dict(step.metadata)\n        metadata["search_teacher_policy"] = list(target.policy_target)\n        metadata["search_teacher_action_semantic_keys"] = list(target.action_semantic_keys)\n        metadata["search_teacher_value"] = float(target.value_target)\n        metadata["search_teacher_weight"] = float(target.weight)\n        steps.append(replace(step, metadata=metadata))\n    print(\n        (\n            "[search-teacher-episode-summary] "\n            f"{episode_label} matchup={episode.matchup} seed={episode.seed} "\n            f"considered_states={considered_states} "\n            f"annotated_states={annotated_states} remaining_budget={remaining_budget}"\n        ),\n        flush=True,\n    )\n    return replace(episode, steps=tuple(steps))\n\n\ndef _legal_action_kind_values_for_step(step: TrajectoryStep) -> tuple[str, ...]:\n    if step.legal_low_level_specs:\n        return tuple(spec.kind.value for spec in step.legal_low_level_specs)\n    kinds: list[str] = []\n    for action_code in step.legal_low_level_codes:\n        kind = try_low_level_kind_for_code(int(action_code))\n        if kind is not None:\n            kinds.append(kind.value)\n    return tuple(kinds)\n\n\ndef _is_search_state(step: TrajectoryStep, *, config: LookaheadSearchConfig) -> bool:\n    if step.request_type.name != "ACTION":\n        return False\n    if step.player_view is None or step.full_state_json_before is None:\n        return False\n    if step.pre_state.round_number >= config.round_threshold:\n        return True\n    if len(step.legal_low_level_codes) >= config.legal_option_threshold:\n        return True\n    legal_kind_values = _legal_action_kind_values_for_step(step)\n    if not legal_kind_values:\n        return False\n    productive_non_end = any(kind_value != "action_declare_end" for kind_value in legal_kind_values)\n    has_end = any(kind_value == "action_declare_end" for kind_value in legal_kind_values)\n    return productive_non_end and has_end\n\n\ndef _search_teacher_target(\n    *,\n    step: TrajectoryStep,\n    matchup: Matchup,\n    model: PpoTransformerPolicy,\n    encoder: TokenObservationEncoder,\n    device: torch.device,\n    env_config: EnvConfig,\n    config: LookaheadSearchConfig,\n    seed: int | None,\n    trace_prefix: str | None = None,\n) -> SearchTeacherTarget | None:\n    root_context = _rebuild_root_context(\n        state_json=step.full_state_json_before,\n        matchup=matchup,\n        env_config=env_config,\n        seed=seed,\n    )\n    if root_context is None or root_context.player_view is None or not root_context.legal_low_level_codes:\n        if trace_prefix is not None and _trace_enabled(config, "root"):\n            print(f"[search-teacher-root-skip] {trace_prefix} reason=rebuild_failed", flush=True)\n        return None\n    root_option_indices = _candidate_indices(\n        context=root_context,\n        model=model,\n        encoder=encoder,\n        device=device,\n        top_k=config.root_top_k,\n    )\n    if not root_option_indices:\n        if trace_prefix is not None and _trace_enabled(config, "root"):\n            print(f"[search-teacher-root-skip] {trace_prefix} reason=no_candidates", flush=True)\n        return None\n    if trace_prefix is not None and _trace_enabled(config, "root"):\n        print(\n            f"[search-teacher-root] {trace_prefix} root_candidates={len(root_option_indices)}",\n            flush=True,\n        )\n    score_by_index: dict[int, float] = {}\n    option_count = len(root_option_indices)\n    for option_position, index in enumerate(root_option_indices, start=1):\n        root_action_code = int(root_context.legal_low_level_codes[index])\n        option_started_at = time.perf_counter()\n        if trace_prefix is not None and _trace_enabled(config, "option"):\n            print(\n                (\n                    "[search-teacher-root-option] "\n                    f"{trace_prefix} option={option_position}/{option_count} "\n                    f"action_code={root_action_code}"\n                ),\n                flush=True,\n            )\n        score_by_index[index] = _evaluate_root_option(\n            step=step,\n            matchup=matchup,\n            env_config=env_config,\n            model=model,\n            encoder=encoder,\n            device=device,\n            action_code=root_action_code,\n            depth=config.depth,\n            seed=seed,\n        )\n        if trace_prefix is not None and _trace_enabled(config, "option"):\n            print(\n                (\n                    "[search-teacher-root-option-done] "\n                    f"{trace_prefix} option={option_position}/{option_count} "\n                    f"score={score_by_index[index]:.4f} "\n                    f"elapsed_ms={(time.perf_counter() - option_started_at) * 1000.0:.1f}"\n                ),\n                flush=True,\n            )\n    if not score_by_index:\n        if trace_prefix is not None and _trace_enabled(config, "root"):\n            print(f"[search-teacher-root-skip] {trace_prefix} reason=no_scores", flush=True)\n        return None\n    base_log_probs = _policy_log_probs(\n        context=root_context,\n        model=model,\n        encoder=encoder,\n        device=device,\n    )\n    teacher_logits = list(base_log_probs)\n    for index, score in score_by_index.items():\n        teacher_logits[index] = float(score) / max(1e-6, config.policy_temperature)\n    policy_target = _softmax_tuple(teacher_logits)\n    best_score = max(score_by_index.values())\n    teacher_weight = max(config.policy_distill_coef, config.value_distill_coef)\n    if trace_prefix is not None and _trace_enabled(config, "root"):\n        print(\n            (\n                "[search-teacher-root-done] "\n                f"{trace_prefix} best_score={best_score:.4f} "\n                f"teacher_weight={teacher_weight:.3f}"\n            ),\n            flush=True,\n        )\n    return SearchTeacherTarget(\n        policy_target=policy_target,\n        action_semantic_keys=tuple(\n            _semantic_key_token_for_code(int(code))\n            for code in root_context.legal_low_level_codes\n        ),\n        value_target=float(best_score),\n        weight=float(teacher_weight),\n    )\n\n\ndef _evaluate_root_option(\n    *,\n    step: TrajectoryStep,\n    matchup: Matchup,\n    env_config: EnvConfig,\n    model: PpoTransformerPolicy,\n    encoder: TokenObservationEncoder,\n    device: torch.device,\n    action_code: int,\n    depth: int,\n    seed: int | None,\n) -> float:\n    env = GitcgDecisionEnv(\n        _teacher_env_config(env_config),\n        matchup,\n        enable_result_based_action_relabel=False,\n    )\n    try:\n        context = env.reset(seed=seed, state_json=step.full_state_json_before)\n        option_index = match_low_level_code_index(context, action_code)\n        if option_index is None:\n            return -1.0\n        next_context, transition, done = env.step(ActionChoice(action_code=context.legal_low_level_codes[option_index]))\n        root_player = int(step.acting_player)\n        if done:\n            return _terminal_value(transition.post_state.winner, root_player=root_player)\n        current_context = next_context\n        remaining_depth = max(0, depth - 1)\n        while remaining_depth > 0 and current_context is not None and not current_context.terminal:\n            greedy_index = _greedy_action_index(\n                context=current_context,\n                model=model,\n                encoder=encoder,\n                device=device,\n            )\n            if greedy_index is None:\n                break\n            current_context, transition, done = env.step(\n                ActionChoice(action_code=current_context.legal_low_level_codes[greedy_index])\n            )\n            if done:\n                return _terminal_value(transition.post_state.winner, root_player=root_player)\n            remaining_depth -= 1\n        if current_context is None:\n            return 0.0\n        privileged_state = torch.as_tensor(\n            encoder.event.encode_privileged_state(current_context.full_state),\n            dtype=torch.float32,\n            device=device,\n        ).unsqueeze(0)\n        with torch.inference_mode():\n            return float(model.oracle_value(privileged_state)[0].item())\n    finally:\n        env.close()\n\n\ndef _candidate_indices(\n    *,\n    context: DecisionContext,\n    model: PpoTransformerPolicy,\n    encoder: TokenObservationEncoder,\n    device: torch.device,\n    top_k: int,\n) -> tuple[int, ...]:\n    if not context.legal_low_level_codes:\n        return ()\n    log_probs = _policy_log_probs(context=context, model=model, encoder=encoder, device=device)\n    ranked = sorted(range(len(log_probs)), key=lambda index: log_probs[index], reverse=True)\n    limit = max(1, min(len(ranked), int(top_k)))\n    return tuple(ranked[:limit])\n\n\ndef _policy_log_probs(\n    *,\n    context: DecisionContext,\n    model: PpoTransformerPolicy,\n    encoder: TokenObservationEncoder,\n    device: torch.device,\n) -> tuple[float, ...]:\n    encoded = encoder.encode_context(context, history=(), include_training_targets=False)\n    token_features = torch.as_tensor(encoded.token_features, dtype=torch.float32, device=device).unsqueeze(0)\n    token_mask = torch.as_tensor(encoded.token_mask, dtype=torch.bool, device=device).unsqueeze(0)\n    opponent_token_mask = torch.as_tensor(encoded.opponent_token_mask, dtype=torch.bool, device=device).unsqueeze(0)\n    option_features = torch.as_tensor(encoded.option_features, dtype=torch.float32, device=device).unsqueeze(0)\n    option_mask = torch.as_tensor(encoded.option_mask, dtype=torch.bool, device=device).unsqueeze(0)\n    opponent_tag_ids = torch.as_tensor([encoded.opponent_tag_id], dtype=torch.long, device=device)\n    opponent_entity_ids = torch.as_tensor([encoded.opponent_entity_id], dtype=torch.long, device=device)\n    opponent_deck_ids = torch.as_tensor([encoded.opponent_deck_id], dtype=torch.long, device=device)\n    with torch.inference_mode():\n        output = model(\n            token_features=token_features,\n            token_mask=token_mask,\n            option_features=option_features,\n            option_mask=option_mask,\n            opponent_token_mask=opponent_token_mask,\n            opponent_tag_ids=opponent_tag_ids,\n            opponent_entity_ids=opponent_entity_ids,\n            opponent_deck_ids=opponent_deck_ids,\n            recurrent_state=None,\n        )\n        log_probs = masked_log_softmax(output.policy_logits[0], option_mask[0])\n    return tuple(float(value) for value in log_probs.detach().cpu().tolist())\n\n\ndef _greedy_action_index(\n    *,\n    context: DecisionContext,\n    model: PpoTransformerPolicy,\n    encoder: TokenObservationEncoder,\n    device: torch.device,\n) -> int | None:\n    if context.player_view is None or not context.legal_low_level_codes:\n        return None\n    log_probs = _policy_log_probs(context=context, model=model, encoder=encoder, device=device)\n    return max(range(len(log_probs)), key=lambda index: log_probs[index])\n\n\ndef _rebuild_root_context(\n    *,\n    state_json: str | None,\n    matchup: Matchup,\n    env_config: EnvConfig,\n    seed: int | None,\n) -> DecisionContext | None:\n    if not state_json:\n        return None\n    env = GitcgDecisionEnv(\n        _teacher_env_config(env_config),\n        matchup,\n        enable_result_based_action_relabel=False,\n    )\n    try:\n        return env.reset(seed=seed, state_json=state_json)\n    except Exception:\n        return None\n    finally:\n        env.close()\n\n\ndef _teacher_env_config(env_config: EnvConfig) -> EnvConfig:\n    return EnvConfig(\n        deck_pool=env_config.deck_pool,\n        version=env_config.version,\n        max_rounds=env_config.max_rounds,\n        seed=env_config.seed,\n        seed_policy=env_config.seed_policy,\n        record_full_state_json=True,\n        record_player_view=True,\n        draw_penalty=env_config.draw_penalty,\n    )\n\n\n\ndef _softmax_tuple(logits: Sequence[float]) -> tuple[float, ...]:\n    if not logits:\n        return ()\n    max_logit = max(logits)\n    exp_values = [math.exp(value - max_logit) for value in logits]\n    total = sum(exp_values)\n    if total <= 0.0:\n        return tuple(1.0 / float(len(logits)) for _ in logits)\n    return tuple(value / total for value in exp_values)\n\n\ndef _terminal_value(winner: int | None, *, root_player: int) -> float:\n    if winner is None:\n        return 0.0\n    return 1.0 if int(winner) == int(root_player) else -1.0\n'
PPO_TRAINING_CONTENT = 'from __future__ import annotations\n\nimport json\nimport math\nfrom contextlib import nullcontext\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Callable, Sequence\n\nimport torch\nimport torch.nn.functional as F\nfrom torch.utils.data import DataLoader, WeightedRandomSampler\n\nfrom .action_quality import (\n    declare_end_waste_ratio,\n    premature_end_severity,\n)\nfrom .action_hierarchy import (\n    aggregate_high_policy,\n    high_action_vocab_size,\n    legal_low_level_specs,\n    selected_low_level_code,\n    semantic_action_key_for_code,\n)\nfrom .lookahead_search import LookaheadSearchConfig, annotate_episodes_with_search_targets\nfrom .public_state import PublicStateTracker\nfrom .ppo_checkpoint import (\n    load_ppo_deployment_checkpoint,\n    load_ppo_training_checkpoint,\n    save_ppo_deployment_checkpoint,\n    save_ppo_training_checkpoint,\n)\nfrom .ppo_features import EncodedObservation, TokenObservationEncoder\nfrom .ppo_model import PpoModelConfig, PpoTransformerPolicy, masked_log_softmax\nfrom .progress import atomic_write_json\nfrom .sepot_search import (\n    SePotSearchConfig,\n    build_public_belief_state,\n    phase_budget_for_context,\n    range_summary,\n    state_search_context_summary,\n)\nfrom .schema import DecisionContext, EnvConfig, EpisodeRecord, TrajectoryStep\n\n\ndef _jsonable_semantic_value(value):\n    if isinstance(value, tuple):\n        return [_jsonable_semantic_value(item) for item in value]\n    if isinstance(value, list):\n        return [_jsonable_semantic_value(item) for item in value]\n    return value\n\n\ndef _semantic_key_token_for_code(action_code: int) -> str:\n    import json\n\n    key = semantic_action_key_for_code(int(action_code))\n    return json.dumps(_jsonable_semantic_value(key), ensure_ascii=False, separators=(",", ":"))\n\n\ndef _normalize_policy(values: Sequence[float]) -> tuple[float, ...]:\n    total = sum(max(0.0, float(value)) for value in values)\n    if total <= 1.0e-8:\n        return tuple(0.0 for _ in values)\n    return tuple(max(0.0, float(value)) / total for value in values)\n\n\ndef _align_search_teacher_policy_target(\n    *,\n    context: DecisionContext,\n    policy: Sequence[float],\n    teacher_action_semantic_keys: Sequence[str] | None = None,\n) -> tuple[float, ...]:\n    current_codes = tuple(int(code) for code in context.legal_low_level_codes)\n    if not current_codes:\n        return ()\n    if not policy:\n        return tuple(0.0 for _ in current_codes)\n\n    if teacher_action_semantic_keys is not None and len(teacher_action_semantic_keys) == len(policy):\n        current_tokens = tuple(_semantic_key_token_for_code(code) for code in current_codes)\n        aligned = [0.0] * len(current_codes)\n        index_by_token = {token: index for index, token in enumerate(current_tokens)}\n        for source_index, token in enumerate(teacher_action_semantic_keys):\n            target_index = index_by_token.get(str(token))\n            if target_index is None:\n                continue\n            aligned[target_index] += float(policy[source_index])\n        normalized = _normalize_policy(aligned)\n        if any(value > 0.0 for value in normalized):\n            return normalized\n        print(\n            "[search-teacher-align] "\n            f"status=drop_all_unmatched semantic current={len(current_codes)} teacher={len(policy)}",\n            flush=True,\n        )\n        return tuple(0.0 for _ in current_codes)\n\n    if len(policy) == len(current_codes):\n        return _normalize_policy(tuple(float(value) for value in policy))\n\n    print(\n        "[search-teacher-align] "\n        f"status=length_mismatch current={len(current_codes)} teacher={len(policy)}",\n        flush=True,\n    )\n    return tuple(0.0 for _ in current_codes)\n\n\n@dataclass(frozen=True)\nclass PpoTrainSample:\n    token_features: tuple[tuple[float, ...], ...]\n    token_mask: tuple[bool, ...]\n    opponent_token_mask: tuple[bool, ...]\n    option_features: tuple[tuple[float, ...], ...]\n    option_mask: tuple[bool, ...]\n    low_level_action_codes: tuple[int, ...]\n    low_to_high_codes: tuple[int, ...]\n    high_level_mask: tuple[bool, ...]\n    opponent_tag_id: int\n    opponent_entity_id: int\n    opponent_deck_id: int\n    action_index: int\n    chosen_low_level_code: int\n    chosen_high_level_code: int\n    old_logprob: float\n    return_target: float\n    advantage: float\n    privileged_state: tuple[float, ...]\n    belief_histogram_target: tuple[float, ...]\n    belief_hand_size_target: float\n    belief_remaining_deck_histogram_target: tuple[float, ...]\n    belief_burst_ready_count_target: float\n    belief_group_hand_target: tuple[float, ...]\n    belief_group_deck_target: tuple[float, ...]\n    search_self_range_summary: tuple[float, ...] = ()\n    search_opponent_range_summary: tuple[float, ...] = ()\n    search_context_summary: tuple[float, ...] = ()\n    search_teacher_policy_target: tuple[float, ...] = ()\n    search_teacher_high_policy_target: tuple[float, ...] = ()\n    search_teacher_value_target: float = 0.0\n    search_teacher_weight: float = 0.0\n    search_acted: float = 0.0\n    sample_weight: float = 1.0\n    round_number: int = 0\n    terminal_draw: bool = False\n    terminal_loss: bool = False\n    close_game: bool = False\n\n\n@dataclass(frozen=True)\nclass PpoTrainChunk:\n    steps: tuple[PpoTrainSample, ...]\n    burn_in: int\n    loss_length: int\n    has_late_round: bool\n    has_terminal_draw: bool\n    has_terminal_loss: bool\n    has_close_game: bool\n\n\n@dataclass(frozen=True)\nclass PpoTrainingMetrics:\n    total_loss: float\n    policy_loss: float\n    high_policy_loss: float\n    fresh_policy_loss: float\n    reference_kl_loss: float\n    value_loss: float\n    replay_value_loss: float\n    entropy: float\n    belief_loss: float\n    replay_belief_loss: float\n    belief_hand_loss: float\n    belief_deck_loss: float\n    belief_burst_loss: float\n    belief_group_hand_loss: float\n    belief_group_deck_loss: float\n    search_distill_loss: float\n    search_policy_loss: float\n    search_value_loss: float\n    oracle_loss: float\n    oracle_distill_loss: float\n    approx_kl: float\n    late_round_sample_ratio: float\n    draw_chunk_ratio: float\n    loss_chunk_ratio: float\n\n\n@dataclass(frozen=True)\nclass PpoTrainArtifacts:\n    output_dir: str\n    training_checkpoint: str\n    deployment_checkpoint: str\n    summary_path: str\n    best_epoch: int\n    best_score: float\n    device: str\n    sample_count: int\n\n\nPpoTrainingProgressCallback = Callable[[int, int, PpoTrainingMetrics, bool], None]\n\n\n@dataclass(frozen=True)\nclass _DecisionTransition:\n    encoded: EncodedObservation\n    source_step: TrajectoryStep\n    search_self_range_summary: tuple[float, ...]\n    search_opponent_range_summary: tuple[float, ...]\n    search_context_summary: tuple[float, ...]\n    action_index: int\n    old_logprob: float\n    value: float\n    reward: float\n    discount: float\n    next_value: float\n    round_number: int\n    terminal_draw: bool\n    terminal_loss: bool\n    close_game: bool\n\n\ndef build_ppo_samples(\n    episodes: Sequence[EpisodeRecord],\n    encoder: TokenObservationEncoder,\n    *,\n    gamma: float = 0.99,\n    gae_lambda: float = 0.95,\n    include_old_logprob: bool = True,\n) -> list[PpoTrainSample]:\n    samples: list[PpoTrainSample] = []\n    for episode in episodes:\n        player_sequences = _build_player_sequences(\n            episode=episode,\n            encoder=encoder,\n            gamma=gamma,\n            gae_lambda=gae_lambda,\n            include_old_logprob=include_old_logprob,\n        )\n        for sequence in player_sequences.values():\n            samples.extend(sequence)\n    return samples\n\n\ndef build_ppo_chunks(\n    episodes: Sequence[EpisodeRecord],\n    encoder: TokenObservationEncoder,\n    *,\n    gamma: float = 0.99,\n    gae_lambda: float = 0.95,\n    include_old_logprob: bool = True,\n    chunk_length: int = 16,\n    burn_in: int = 4,\n    train_length: int = 12,\n) -> list[PpoTrainChunk]:\n    chunks: list[PpoTrainChunk] = []\n    for episode in episodes:\n        player_sequences = _build_player_sequences(\n            episode=episode,\n            encoder=encoder,\n            gamma=gamma,\n            gae_lambda=gae_lambda,\n            include_old_logprob=include_old_logprob,\n        )\n        for sequence in player_sequences.values():\n            chunks.extend(\n                _chunk_player_sequence(\n                    sequence,\n                    chunk_length=chunk_length,\n                    burn_in=burn_in,\n                    train_length=train_length,\n                )\n            )\n    return chunks\n\n\ndef bootstrap_pretrain_from_episodes(\n    *,\n    episodes: Sequence[EpisodeRecord],\n    output_dir: str | Path,\n    init_checkpoint: str | Path | None = None,\n    device: str = "cpu",\n    batch_size: int = 32,\n    micro_batch_size: int | None = None,\n    epochs: int = 5,\n    learning_rate: float = 1e-3,\n    weight_decay: float = 1e-4,\n    grad_clip_norm: float | None = 1.0,\n    use_amp: bool | None = None,\n    chunk_length: int = 16,\n    burn_in: int = 4,\n    train_length: int = 12,\n    progress_callback: PpoTrainingProgressCallback | None = None,\n) -> PpoTrainArtifacts:\n    encoder = _encoder_for_init_checkpoint(init_checkpoint)\n    fresh_chunks = build_ppo_chunks(\n        episodes,\n        encoder,\n        include_old_logprob=False,\n        chunk_length=chunk_length,\n        burn_in=burn_in,\n        train_length=train_length,\n    )\n    return _fit_actor_critic(\n        fresh_chunks=fresh_chunks,\n        replay_chunks=(),\n        output_dir=output_dir,\n        init_checkpoint=init_checkpoint,\n        reference_checkpoint=None,\n        device=device,\n        batch_size=batch_size,\n        micro_batch_size=micro_batch_size,\n        epochs=epochs,\n        learning_rate=learning_rate,\n        weight_decay=weight_decay,\n        grad_clip_norm=grad_clip_norm,\n        use_amp=use_amp,\n        objective="behavior_clone",\n        chunk_length=chunk_length,\n        burn_in=burn_in,\n        train_length=train_length,\n        progress_callback=progress_callback,\n    )\n\n\ndef train_ppo_from_episodes(\n    *,\n    episodes: Sequence[EpisodeRecord],\n    replay_episodes: Sequence[EpisodeRecord] | None = None,\n    output_dir: str | Path,\n    init_checkpoint: str | Path | None = None,\n    env_config: EnvConfig | None = None,\n    device: str = "cpu",\n    batch_size: int = 32,\n    micro_batch_size: int | None = None,\n    epochs: int = 12,\n    replay_epochs: int = 2,\n    learning_rate: float = 1.0e-3,\n    weight_decay: float = 1e-4,\n    grad_clip_norm: float | None = 1.0,\n    gamma: float = 0.99,\n    gae_lambda: float = 0.95,\n    entropy_coef: float = 0.01,\n    policy_coef: float = 4.0,\n    value_coef: float = 0.5,\n    belief_coef: float = 0.2,\n    oracle_coef: float = 0.2,\n    use_amp: bool | None = None,\n    chunk_length: int = 16,\n    burn_in: int = 4,\n    train_length: int = 12,\n    reference_kl_coef: float = 0.005,\n    target_kl_low: float = 0.01,\n    target_kl_high: float = 0.05,\n    search_teacher_config: LookaheadSearchConfig | None = None,\n    progress_callback: PpoTrainingProgressCallback | None = None,\n) -> PpoTrainArtifacts:\n    encoder = _encoder_for_init_checkpoint(init_checkpoint)\n    resolved_search_config = search_teacher_config or LookaheadSearchConfig()\n    training_episodes = tuple(episodes)\n    if resolved_search_config.enabled and env_config is not None:\n        teacher_model = _load_search_teacher_model(\n            init_checkpoint=init_checkpoint,\n            encoder=encoder,\n            device=device,\n        )\n        training_episodes = annotate_episodes_with_search_targets(\n            training_episodes,\n            model=teacher_model,\n            encoder=encoder,\n            device=torch.device(device),\n            env_config=env_config,\n            config=resolved_search_config,\n        )\n    fresh_chunks = build_ppo_chunks(\n        training_episodes,\n        encoder,\n        gamma=gamma,\n        gae_lambda=gae_lambda,\n        include_old_logprob=True,\n        chunk_length=chunk_length,\n        burn_in=burn_in,\n        train_length=train_length,\n    )\n    replay_chunks = _select_aux_replay_chunks(\n        build_ppo_chunks(\n            tuple(replay_episodes or ()),\n            encoder,\n            gamma=gamma,\n            gae_lambda=gae_lambda,\n            include_old_logprob=True,\n            chunk_length=chunk_length,\n            burn_in=burn_in,\n            train_length=train_length,\n        )\n    )\n    return _fit_actor_critic(\n        fresh_chunks=fresh_chunks,\n        replay_chunks=replay_chunks,\n        output_dir=output_dir,\n        init_checkpoint=init_checkpoint,\n        reference_checkpoint=init_checkpoint,\n        device=device,\n        batch_size=batch_size,\n        micro_batch_size=micro_batch_size,\n        epochs=epochs,\n        replay_epochs=replay_epochs,\n        learning_rate=learning_rate,\n        weight_decay=weight_decay,\n        grad_clip_norm=grad_clip_norm,\n        objective="ppo",\n        entropy_coef=entropy_coef,\n        policy_coef=policy_coef,\n        value_coef=value_coef,\n        belief_coef=belief_coef,\n        oracle_coef=oracle_coef,\n        use_amp=use_amp,\n        chunk_length=chunk_length,\n        burn_in=burn_in,\n        train_length=train_length,\n        reference_kl_coef=reference_kl_coef,\n        target_kl_low=target_kl_low,\n        target_kl_high=target_kl_high,\n        progress_callback=progress_callback,\n    )\n\n\ndef load_ppo_train_artifacts(output_dir: str | Path) -> PpoTrainArtifacts | None:\n    destination = Path(output_dir)\n    summary_path = destination / "training_summary.json"\n    training_checkpoint = destination / "last.pt"\n    deployment_checkpoint = destination / "deployment.pt"\n    if not summary_path.exists() or not training_checkpoint.exists() or not deployment_checkpoint.exists():\n        return None\n    payload = json.loads(summary_path.read_text(encoding="utf-8"))\n    return PpoTrainArtifacts(\n        output_dir=str(destination),\n        training_checkpoint=str(training_checkpoint),\n        deployment_checkpoint=str(deployment_checkpoint),\n        summary_path=str(summary_path),\n        best_epoch=int(payload["best_epoch"]),\n        best_score=float(payload["best_score"]),\n        device=str(payload["device"]),\n        sample_count=int(payload["sample_count"]),\n    )\n\n\ndef _encoder_for_init_checkpoint(init_checkpoint: str | Path | None) -> TokenObservationEncoder:\n    if init_checkpoint is None:\n        return TokenObservationEncoder()\n    checkpoint_path = Path(init_checkpoint)\n    if not checkpoint_path.exists():\n        return TokenObservationEncoder()\n    try:\n        _, encoder, _, _ = load_ppo_training_checkpoint(checkpoint_path, device="cpu")\n        return encoder\n    except Exception:\n        try:\n            _, encoder, _ = load_ppo_deployment_checkpoint(checkpoint_path, device="cpu")\n            return encoder\n        except Exception:\n            return TokenObservationEncoder()\n\n\ndef _load_search_teacher_model(\n    *,\n    init_checkpoint: str | Path | None,\n    encoder: TokenObservationEncoder,\n    device: str,\n) -> PpoTransformerPolicy:\n    if init_checkpoint is not None:\n        checkpoint_path = Path(init_checkpoint)\n        if checkpoint_path.exists():\n            try:\n                model, _, _, _ = load_ppo_training_checkpoint(checkpoint_path, device=device)\n                model.eval()\n                return model\n            except Exception:\n                try:\n                    model, _, _ = load_ppo_deployment_checkpoint(checkpoint_path, device=device)\n                    model.eval()\n                    return model\n                except Exception:\n                    pass\n    resolved_device = torch.device(device)\n    model = PpoTransformerPolicy(\n        PpoModelConfig(\n            token_dim=encoder.token_dim,\n            option_dim=encoder.option_dim,\n            high_action_dim=encoder.high_action_dim,\n            privileged_dim=encoder.privileged_state_dim,\n            belief_histogram_dim=encoder.belief_histogram_dim,\n            belief_deck_histogram_dim=encoder.belief_remaining_deck_histogram_dim,\n            max_tokens=encoder.max_tokens,\n            belief_group_dim=encoder.belief_group_dim,\n            opponent_tag_vocab_size=encoder.opponent_tag_vocab_size if encoder.config.include_opponent_tag else 0,\n            opponent_entity_vocab_size=encoder.opponent_entity_vocab_size,\n            deck_vocab_size=encoder.deck_vocab_size,\n            search_range_summary_dim=(encoder.belief_histogram_dim * 2) + 12,\n            search_context_dim=16,\n        )\n    )\n    model.to(resolved_device)\n    model.eval()\n    return model\n\n\ndef _build_player_sequences(\n    *,\n    episode: EpisodeRecord,\n    encoder: TokenObservationEncoder,\n    gamma: float,\n    gae_lambda: float,\n    include_old_logprob: bool,\n) -> dict[int, list[PpoTrainSample]]:\n    encoded_steps: dict[int, dict[str, object]] = {}\n    trainable_by_player: dict[int, list[int]] = {0: [], 1: []}\n    history: list[TrajectoryStep] = []\n    public_trackers = {\n        0: PublicStateTracker(player_id=0),\n        1: PublicStateTracker(player_id=1),\n    }\n    search_config = SePotSearchConfig()\n    zero_belief_histogram = tuple(0.0 for _ in range(encoder.belief_histogram_dim))\n    zero_belief_deck_histogram = tuple(0.0 for _ in range(encoder.belief_remaining_deck_histogram_dim))\n    for step_index, step in enumerate(episode.steps):\n        context = _context_from_step(step, episode_metadata=episode.metadata)\n        is_trainable = bool(step.metadata.get("ppo_trainable", True))\n        if is_trainable:\n            tracker = public_trackers[step.acting_player]\n            opponent_deck_name = str(\n                context.metadata.get("opponent_deck_name")\n                or ""\n            )\n            encoded = encoder.encode_context(\n                context,\n                history=tuple(history[-encoder.config.max_history_tokens :]),\n                opponent_tag=str(context.metadata.get("opponent_tag", "unknown")),\n                opponent_entity_key=str(context.metadata.get("opponent_entity_key", "unknown")),\n                opponent_deck_name=opponent_deck_name,\n                opponent_public_dice_count=tracker.opponent_public_dice_count(context),\n            )\n            budget = phase_budget_for_context(context, config=search_config)\n            public_belief = build_public_belief_state(\n                context=context,\n                tracker=tracker,\n                card_vocabulary=encoder.config.card_vocabulary,\n                opponent_deck_name=(opponent_deck_name or "unknown"),\n                belief_histogram=zero_belief_histogram,\n                belief_remaining_deck_histogram=zero_belief_deck_histogram,\n                belief_samples=budget.belief_samples,\n            )\n            encoded_steps[step_index] = {\n                "encoded": encoded,\n                "action_index": _selected_action_index(step),\n                "old_logprob": float(step.metadata.get("selected_logprob", 0.0))\n                if include_old_logprob\n                else 0.0,\n                "value": float(step.metadata.get("partial_value", 0.0)),\n                "search_self_range_summary": range_summary(\n                    public_belief.self_range,\n                    card_vocabulary=encoder.config.card_vocabulary,\n                ),\n                "search_opponent_range_summary": range_summary(\n                    public_belief.opponent_range,\n                    card_vocabulary=encoder.config.card_vocabulary,\n                ),\n                "search_context_summary": state_search_context_summary(\n                    context=context,\n                    budget=budget,\n                ),\n            }\n            trainable_by_player[step.acting_player].append(step_index)\n        for tracker in public_trackers.values():\n            tracker.observe_step(step)\n        history.append(step)\n\n    result: dict[int, list[PpoTrainSample]] = {0: [], 1: []}\n    for player, indices in trainable_by_player.items():\n        if not indices:\n            continue\n        transitions: list[_DecisionTransition] = []\n        value_lookup = {index: float(encoded_steps[index]["value"]) for index in indices}\n        for offset, step_index in enumerate(indices):\n            next_index = indices[offset + 1] if offset + 1 < len(indices) else None\n            reward, discount = _accumulate_reward_until_next_trainable(\n                episode.steps,\n                start_index=step_index,\n                next_trainable_index=next_index,\n                perspective_player=player,\n                gamma=gamma,\n            )\n            item = encoded_steps[step_index]\n            source_step = episode.steps[step_index]\n            transitions.append(\n                _DecisionTransition(\n                    encoded=item["encoded"],  # type: ignore[arg-type]\n                    source_step=source_step,\n                    search_self_range_summary=tuple(float(value) for value in item["search_self_range_summary"]),  # type: ignore[index]\n                    search_opponent_range_summary=tuple(float(value) for value in item["search_opponent_range_summary"]),  # type: ignore[index]\n                    search_context_summary=tuple(float(value) for value in item["search_context_summary"]),  # type: ignore[index]\n                    action_index=int(item["action_index"]),\n                    old_logprob=float(item["old_logprob"]),\n                    value=float(item["value"]),\n                    reward=reward,\n                    discount=discount,\n                    next_value=(value_lookup.get(next_index, 0.0) if next_index is not None else 0.0),\n                    round_number=source_step.pre_state.round_number,\n                    terminal_draw=bool(source_step.done and episode.winner is None),\n                    terminal_loss=bool(source_step.done and episode.winner is not None and episode.winner != player),\n                    close_game=abs(_potential(source_step.pre_state, perspective_player=player)) <= 0.10,\n                )\n            )\n        returns, advantages = _gae_returns(transitions, gae_lambda=gae_lambda)\n        for transition, return_target, advantage in zip(transitions, returns, advantages):\n            encoded = transition.encoded\n            transition_context = _context_from_step(transition.source_step, episode_metadata=episode.metadata)\n            raw_search_teacher_policy_target = tuple(\n                float(value) for value in transition.source_step.metadata.get("search_teacher_policy", ())\n            )\n            raw_search_teacher_action_semantic_keys = tuple(\n                str(value)\n                for value in transition.source_step.metadata.get("search_teacher_action_semantic_keys", ())\n            )\n            search_teacher_policy_target = _align_search_teacher_policy_target(\n                context=transition_context,\n                policy=raw_search_teacher_policy_target,\n                teacher_action_semantic_keys=(\n                    raw_search_teacher_action_semantic_keys\n                    if raw_search_teacher_action_semantic_keys\n                    else None\n                ),\n            )\n            result[player].append(\n                PpoTrainSample(\n                    token_features=encoded.token_features,\n                    token_mask=encoded.token_mask,\n                    opponent_token_mask=encoded.opponent_token_mask,\n                    option_features=encoded.option_features,\n                    option_mask=encoded.option_mask,\n                    low_level_action_codes=encoded.low_level_action_codes,\n                    low_to_high_codes=encoded.low_to_high_codes,\n                    high_level_mask=encoded.high_level_mask,\n                    opponent_tag_id=encoded.opponent_tag_id,\n                    opponent_entity_id=encoded.opponent_entity_id,\n                    opponent_deck_id=encoded.opponent_deck_id,\n                    action_index=transition.action_index,\n                    chosen_low_level_code=int(\n                        transition.source_step.choice.action_code\n                        if transition.source_step.choice.action_code >= 0\n                        else encoded.low_level_action_codes[transition.action_index]\n                    ),\n                    chosen_high_level_code=int(\n                        transition.source_step.chosen_high_level_code\n                        if (\n                            transition.source_step.chosen_high_level_code is not None\n                            and int(transition.source_step.chosen_high_level_code)\n                            in {int(code) for code in transition.source_step.legal_high_level_codes}\n                        )\n                        else encoded.low_to_high_codes[transition.action_index]\n                    ),\n                    old_logprob=transition.old_logprob,\n                    return_target=float(return_target),\n                    advantage=float(advantage),\n                    privileged_state=encoded.privileged_state,\n                    belief_histogram_target=encoded.belief_target.hand_histogram,\n                    belief_hand_size_target=encoded.belief_target.hand_size,\n                    belief_remaining_deck_histogram_target=encoded.belief_target.remaining_deck_histogram,\n                    belief_burst_ready_count_target=encoded.belief_target.burst_ready_count,\n                    belief_group_hand_target=encoded.belief_target.group_hand_presence,\n                    belief_group_deck_target=encoded.belief_target.group_remaining_deck_presence,\n                    search_self_range_summary=transition.search_self_range_summary,\n                    search_opponent_range_summary=transition.search_opponent_range_summary,\n                    search_context_summary=transition.search_context_summary,\n                    search_teacher_policy_target=search_teacher_policy_target,\n                    search_teacher_high_policy_target=aggregate_high_policy(\n                        context=transition_context,\n                        low_level_policy=search_teacher_policy_target,\n                    )\n                    if search_teacher_policy_target\n                    else tuple(0.0 for _ in range(high_action_vocab_size())),\n                    search_teacher_value_target=float(transition.source_step.metadata.get("search_teacher_value", 0.0)),\n                    search_teacher_weight=float(transition.source_step.metadata.get("search_teacher_weight", 0.0)),\n                    search_acted=float(transition.source_step.metadata.get("search_acted", 0.0)),\n                    sample_weight=_sample_weight(\n                        episode=episode,\n                        perspective_player=player,\n                        round_number=transition.round_number,\n                    ),\n                    round_number=transition.round_number,\n                    terminal_draw=transition.terminal_draw,\n                    terminal_loss=transition.terminal_loss,\n                    close_game=transition.close_game,\n                )\n            )\n    return result\n\n\ndef _chunk_player_sequence(\n    sequence: Sequence[PpoTrainSample],\n    *,\n    chunk_length: int,\n    burn_in: int,\n    train_length: int,\n) -> list[PpoTrainChunk]:\n    if not sequence:\n        return []\n    chunks: list[PpoTrainChunk] = []\n    stride = max(1, train_length)\n    total = len(sequence)\n    start = 0\n    while start < total:\n        end = min(total, start + chunk_length)\n        steps = tuple(sequence[start:end])\n        if not steps:\n            break\n        local_burn_in = min(burn_in, max(0, len(steps) - 1))\n        loss_length = max(1, len(steps) - local_burn_in)\n        chunks.append(\n            PpoTrainChunk(\n                steps=steps,\n                burn_in=local_burn_in,\n                loss_length=loss_length,\n                has_late_round=any(step.round_number >= 13 for step in steps),\n                has_terminal_draw=any(step.terminal_draw for step in steps),\n                has_terminal_loss=any(step.terminal_loss for step in steps),\n                has_close_game=any(step.close_game for step in steps),\n            )\n        )\n        start += stride\n    return chunks\n\n\ndef _select_aux_replay_chunks(chunks: Sequence[PpoTrainChunk]) -> tuple[PpoTrainChunk, ...]:\n    return tuple(\n        chunk\n        for chunk in chunks\n        if chunk.has_late_round or chunk.has_terminal_draw or chunk.has_terminal_loss or chunk.has_close_game\n    )\n\n\ndef _fit_actor_critic(\n    *,\n    fresh_chunks: Sequence[PpoTrainChunk],\n    replay_chunks: Sequence[PpoTrainChunk],\n    output_dir: str | Path,\n    init_checkpoint: str | Path | None,\n    reference_checkpoint: str | Path | None,\n    device: str,\n    batch_size: int,\n    micro_batch_size: int | None,\n    epochs: int,\n    replay_epochs: int = 0,\n    learning_rate: float,\n    weight_decay: float,\n    grad_clip_norm: float | None,\n    use_amp: bool | None,\n    objective: str,\n    entropy_coef: float = 0.01,\n    policy_coef: float = 4.0,\n    value_coef: float = 0.5,\n    belief_coef: float = 0.2,\n    oracle_coef: float = 0.2,\n    chunk_length: int = 16,\n    burn_in: int = 4,\n    train_length: int = 12,\n    reference_kl_coef: float = 0.005,\n    target_kl_low: float = 0.01,\n    target_kl_high: float = 0.05,\n    progress_callback: PpoTrainingProgressCallback | None = None,\n) -> PpoTrainArtifacts:\n    if not fresh_chunks:\n        raise RuntimeError("no PPO chunks available")\n    destination = Path(output_dir)\n    destination.mkdir(parents=True, exist_ok=True)\n    resolved_device = torch.device(device)\n    if init_checkpoint is not None:\n        try:\n            model, encoder, parent_metadata, optimizer_state = load_ppo_training_checkpoint(\n                init_checkpoint,\n                device=device,\n            )\n        except Exception:\n            model, encoder, parent_metadata = load_ppo_deployment_checkpoint(init_checkpoint, device=device)\n            optimizer_state = None\n    else:\n        encoder = TokenObservationEncoder()\n        model = PpoTransformerPolicy(\n            PpoModelConfig(\n                token_dim=encoder.token_dim,\n                option_dim=encoder.option_dim,\n                high_action_dim=encoder.high_action_dim,\n                privileged_dim=encoder.privileged_state_dim,\n                belief_histogram_dim=encoder.belief_histogram_dim,\n                belief_deck_histogram_dim=encoder.belief_remaining_deck_histogram_dim,\n                max_tokens=encoder.max_tokens,\n                belief_group_dim=encoder.belief_group_dim,\n                opponent_tag_vocab_size=encoder.opponent_tag_vocab_size if encoder.config.include_opponent_tag else 0,\n                opponent_entity_vocab_size=encoder.opponent_entity_vocab_size,\n                deck_vocab_size=encoder.deck_vocab_size,\n                search_range_summary_dim=(encoder.belief_histogram_dim * 2) + 12,\n                search_context_dim=16,\n            )\n        )\n        model.to(resolved_device)\n        parent_metadata = {}\n        optimizer_state = None\n    optimizer = torch.optim.AdamW(model.parameters(), lr=learning_rate, weight_decay=weight_decay)\n    if optimizer_state is not None:\n        optimizer.load_state_dict(optimizer_state)\n    resolved_use_amp = bool(use_amp) if use_amp is not None else resolved_device.type == "cuda"\n    resolved_micro_batch_size = _resolve_micro_batch_size(\n        batch_size=batch_size,\n        requested_micro_batch_size=micro_batch_size,\n        param_count=sum(parameter.numel() for parameter in model.parameters()),\n        device=resolved_device,\n    )\n    scaler = torch.amp.GradScaler("cuda", enabled=resolved_use_amp and resolved_device.type == "cuda")\n    reference_model = _load_reference_model(reference_checkpoint, device=device) if objective == "ppo" else None\n    fresh_loader = _build_chunk_loader(fresh_chunks, batch_size=batch_size, objective=objective)\n    replay_loader = (\n        _build_chunk_loader(replay_chunks, batch_size=batch_size, objective="aux_replay")\n        if replay_chunks\n        else None\n    )\n\n    history: list[dict[str, float]] = []\n    best_score = float("inf")\n    best_epoch = 0\n    best_state = {key: value.detach().cpu().clone() for key, value in model.state_dict().items()}\n    latest_checkpoint = destination / "last.pt"\n    deployment_checkpoint = destination / "deployment.pt"\n    candidate_dir = destination / "candidates"\n    candidate_epochs: list[int] = []\n    if objective == "ppo":\n        candidate_dir.mkdir(parents=True, exist_ok=True)\n    replay_chunk_count = len(replay_chunks)\n    static_ratios = _dataset_ratios(fresh_chunks=fresh_chunks, replay_chunks=replay_chunks)\n    effective_epochs = int(epochs)\n\n    for epoch_index in range(epochs):\n        main_metrics = _run_training_epoch(\n            model=model,\n            loader=fresh_loader,\n            optimizer=optimizer,\n            device=resolved_device,\n            grad_clip_norm=grad_clip_norm,\n            scaler=scaler,\n            use_amp=resolved_use_amp,\n            micro_batch_size=resolved_micro_batch_size,\n            objective=objective,\n            entropy_coef=entropy_coef,\n            policy_coef=policy_coef if objective == "ppo" else 1.0,\n            value_coef=value_coef,\n            belief_coef=belief_coef,\n            oracle_coef=oracle_coef,\n            reference_model=reference_model,\n            reference_kl_coef=reference_kl_coef if objective == "ppo" else 0.0,\n        )\n        replay_value_loss = 0.0\n        replay_belief_loss = 0.0\n        if replay_loader is not None and replay_epochs > 0:\n            replay_value_total = 0.0\n            replay_belief_total = 0.0\n            for _ in range(replay_epochs):\n                aux_metrics = _run_training_epoch(\n                    model=model,\n                    loader=replay_loader,\n                    optimizer=optimizer,\n                    device=resolved_device,\n                    grad_clip_norm=grad_clip_norm,\n                    scaler=scaler,\n                    use_amp=resolved_use_amp,\n                    micro_batch_size=resolved_micro_batch_size,\n                    objective="aux_replay",\n                    entropy_coef=0.0,\n                    policy_coef=1.0,\n                    value_coef=value_coef,\n                    belief_coef=belief_coef,\n                    oracle_coef=oracle_coef,\n                    reference_model=None,\n                    reference_kl_coef=0.0,\n                )\n                replay_value_total += aux_metrics["value_loss"]\n                replay_belief_total += aux_metrics["belief_loss"]\n            replay_value_loss = replay_value_total / replay_epochs\n            replay_belief_loss = replay_belief_total / replay_epochs\n\n        metrics = PpoTrainingMetrics(\n            total_loss=main_metrics["total_loss"] + 0.5 * replay_value_loss + 0.2 * replay_belief_loss,\n            policy_loss=main_metrics["policy_loss"],\n            high_policy_loss=main_metrics.get("high_policy_loss", 0.0),\n            fresh_policy_loss=main_metrics["policy_loss"],\n            reference_kl_loss=main_metrics["reference_kl_loss"],\n            value_loss=main_metrics["value_loss"],\n            replay_value_loss=replay_value_loss,\n            entropy=main_metrics["entropy"],\n            belief_loss=main_metrics["belief_loss"],\n            replay_belief_loss=replay_belief_loss,\n            belief_hand_loss=main_metrics["belief_hand_loss"],\n            belief_deck_loss=main_metrics["belief_deck_loss"],\n            belief_burst_loss=main_metrics["belief_burst_loss"],\n            belief_group_hand_loss=main_metrics["belief_group_hand_loss"],\n            belief_group_deck_loss=main_metrics["belief_group_deck_loss"],\n            search_distill_loss=main_metrics.get("search_distill_loss", 0.0),\n            search_policy_loss=main_metrics.get("search_policy_loss", 0.0),\n            search_value_loss=main_metrics.get("search_value_loss", 0.0),\n            oracle_loss=main_metrics["oracle_loss"],\n            oracle_distill_loss=main_metrics["oracle_distill_loss"],\n            approx_kl=main_metrics["approx_kl"],\n            late_round_sample_ratio=static_ratios["late_round_sample_ratio"],\n            draw_chunk_ratio=static_ratios["draw_chunk_ratio"],\n            loss_chunk_ratio=static_ratios["loss_chunk_ratio"],\n        )\n        history.append(metrics.__dict__)\n        is_best = False\n        if metrics.total_loss < best_score:\n            best_score = metrics.total_loss\n            best_epoch = epoch_index + 1\n            best_state = {key: value.detach().cpu().clone() for key, value in model.state_dict().items()}\n            is_best = True\n        if progress_callback is not None:\n            progress_callback(epoch_index + 1, epochs, metrics, is_best)\n        save_ppo_training_checkpoint(\n            latest_checkpoint,\n            model,\n            encoder,\n            metadata={\n                "objective": objective,\n                "epoch": epoch_index + 1,\n                "parent_metadata": parent_metadata,\n                "history": history,\n                "chunk_length": chunk_length,\n                "burn_in": burn_in,\n                "train_length": train_length,\n                "replay_chunk_count": replay_chunk_count,\n                "micro_batch_size": resolved_micro_batch_size,\n                "use_amp": resolved_use_amp,\n            },\n            optimizer_state=optimizer.state_dict(),\n        )\n        if objective == "ppo":\n            epoch_number = epoch_index + 1\n            candidate_epochs.append(epoch_number)\n            save_ppo_deployment_checkpoint(\n                candidate_dir / f"epoch_{epoch_number:03d}.pt",\n                model,\n                encoder,\n                metadata={\n                    "objective": objective,\n                    "epoch": epoch_number,\n                    "metrics": metrics.__dict__,\n                },\n            )\n            if metrics.approx_kl > target_kl_high:\n                effective_epochs = epoch_number\n                break\n    model.load_state_dict(best_state)\n    save_ppo_deployment_checkpoint(\n        deployment_checkpoint,\n        model,\n        encoder,\n        metadata={\n            "objective": objective,\n            "best_epoch": best_epoch,\n            "best_score": best_score,\n        },\n    )\n    summary_path = destination / "training_summary.json"\n    atomic_write_json(\n        summary_path,\n        {\n            "objective": objective,\n            "device": device,\n            "best_epoch": best_epoch,\n            "best_score": best_score,\n            "sample_count": sum(len(chunk.steps) for chunk in fresh_chunks),\n            "history": history,\n            "candidate_epochs": candidate_epochs,\n            "safe_epochs": (\n                [index + 1 for index, item in enumerate(history) if all(math.isfinite(float(value)) for value in item.values())]\n                if objective != "ppo"\n                else []\n            ),\n            "selection_method": "min_total_loss" if objective != "ppo" else None,\n            "selected_epoch": best_epoch if objective != "ppo" else None,\n            "chunk_length": chunk_length,\n            "burn_in": burn_in,\n            "train_length": train_length,\n            "replay_chunk_count": replay_chunk_count,\n            "replay_epochs": replay_epochs if objective == "ppo" else 0,\n            "policy_coef": policy_coef if objective == "ppo" else 1.0,\n            "reference_kl_coef": reference_kl_coef if objective == "ppo" else 0.0,\n            "target_kl_low": target_kl_low if objective == "ppo" else 0.0,\n            "target_kl_high": target_kl_high if objective == "ppo" else 0.0,\n            "effective_epochs": effective_epochs,\n            "micro_batch_size": resolved_micro_batch_size,\n            "use_amp": resolved_use_amp,\n            **static_ratios,\n        },\n    )\n    return PpoTrainArtifacts(\n        output_dir=str(destination),\n        training_checkpoint=str(latest_checkpoint),\n        deployment_checkpoint=str(deployment_checkpoint),\n        summary_path=str(summary_path),\n        best_epoch=best_epoch,\n        best_score=best_score,\n        device=device,\n        sample_count=sum(len(chunk.steps) for chunk in fresh_chunks),\n    )\n\n\ndef _build_chunk_loader(\n    chunks: Sequence[PpoTrainChunk],\n    *,\n    batch_size: int,\n    objective: str,\n) -> DataLoader:\n    chunk_list = list(chunks)\n    if objective == "ppo":\n        weights = [_chunk_sampling_weight(chunk) for chunk in chunk_list]\n        sampler = WeightedRandomSampler(weights, num_samples=len(chunk_list), replacement=True)\n        return DataLoader(chunk_list, batch_size=batch_size, sampler=sampler, collate_fn=_collate_chunks)\n    return DataLoader(chunk_list, batch_size=batch_size, shuffle=True, collate_fn=_collate_chunks)\n\n\ndef _chunk_sampling_weight(chunk: PpoTrainChunk) -> float:\n    weight = 1.0\n    if chunk.has_late_round:\n        weight *= 2.0\n    if chunk.has_terminal_draw or chunk.has_terminal_loss:\n        weight *= 2.0\n    if chunk.has_close_game:\n        weight *= 1.5\n    return min(3.0, weight)\n\n\ndef _run_training_epoch(\n    *,\n    model: PpoTransformerPolicy,\n    loader: DataLoader,\n    optimizer: torch.optim.Optimizer,\n    device: torch.device,\n    grad_clip_norm: float | None,\n    scaler: torch.amp.GradScaler | None,\n    use_amp: bool,\n    micro_batch_size: int,\n    objective: str,\n    entropy_coef: float,\n    policy_coef: float,\n    value_coef: float,\n    belief_coef: float,\n    oracle_coef: float,\n    reference_model: PpoTransformerPolicy | None,\n    reference_kl_coef: float,\n) -> dict[str, float]:\n    model.train()\n    aggregate = {\n        "total_loss": 0.0,\n        "policy_loss": 0.0,\n        "high_policy_loss": 0.0,\n        "reference_kl_loss": 0.0,\n        "value_loss": 0.0,\n        "entropy": 0.0,\n        "belief_loss": 0.0,\n        "belief_hand_loss": 0.0,\n        "belief_deck_loss": 0.0,\n        "belief_burst_loss": 0.0,\n        "belief_group_hand_loss": 0.0,\n        "belief_group_deck_loss": 0.0,\n        "search_distill_loss": 0.0,\n        "search_policy_loss": 0.0,\n        "search_value_loss": 0.0,\n        "oracle_loss": 0.0,\n        "oracle_distill_loss": 0.0,\n        "approx_kl": 0.0,\n        "batches": 0,\n    }\n    for batch in loader:\n        batch_loss_steps = int(batch["loss_mask"].sum().item())\n        if batch_loss_steps <= 0:\n            continue\n        optimizer.zero_grad(set_to_none=True)\n        batch_metrics = {\n            "total_loss": 0.0,\n            "policy_loss": 0.0,\n            "high_policy_loss": 0.0,\n            "reference_kl_loss": 0.0,\n            "value_loss": 0.0,\n            "entropy": 0.0,\n            "belief_loss": 0.0,\n            "belief_hand_loss": 0.0,\n            "belief_deck_loss": 0.0,\n            "belief_burst_loss": 0.0,\n            "belief_group_hand_loss": 0.0,\n            "belief_group_deck_loss": 0.0,\n            "search_distill_loss": 0.0,\n            "search_policy_loss": 0.0,\n            "search_value_loss": 0.0,\n            "oracle_loss": 0.0,\n            "oracle_distill_loss": 0.0,\n            "approx_kl": 0.0,\n        }\n        batch_items = int(batch["step_mask"].shape[0])\n        for start in range(0, batch_items, micro_batch_size):\n            stop = min(batch_items, start + micro_batch_size)\n            micro_batch = _slice_chunk_batch(batch, start, stop)\n            micro_loss_steps = int(micro_batch["loss_mask"].sum().item())\n            if micro_loss_steps <= 0:\n                continue\n            amp_context = (\n                torch.amp.autocast(device_type="cuda", dtype=torch.float16, enabled=True)\n                if use_amp and device.type == "cuda"\n                else nullcontext()\n            )\n            with amp_context:\n                loss, metrics, loss_steps = _compute_chunk_batch_loss(\n                    model=model,\n                    batch=micro_batch,\n                    device=device,\n                    objective=objective,\n                    entropy_coef=entropy_coef,\n                    policy_coef=policy_coef,\n                    value_coef=value_coef,\n                    belief_coef=belief_coef,\n                    oracle_coef=oracle_coef,\n                    reference_model=reference_model,\n                    reference_kl_coef=reference_kl_coef,\n                )\n            scale = float(loss_steps) / float(batch_loss_steps)\n            scaled_loss = loss * scale\n            if scaler is not None and scaler.is_enabled():\n                scaler.scale(scaled_loss).backward()\n            else:\n                scaled_loss.backward()\n            for key in batch_metrics:\n                batch_metrics[key] += metrics[key] * scale\n        if grad_clip_norm is not None:\n            if scaler is not None and scaler.is_enabled():\n                scaler.unscale_(optimizer)\n            torch.nn.utils.clip_grad_norm_(model.parameters(), grad_clip_norm)\n        if scaler is not None and scaler.is_enabled():\n            scaler.step(optimizer)\n            scaler.update()\n        else:\n            optimizer.step()\n        for key in aggregate:\n            if key == "batches":\n                continue\n            aggregate[key] += batch_metrics[key]\n        aggregate["batches"] += 1\n    batches = max(1, int(aggregate["batches"]))\n    return {\n        key: (aggregate[key] / batches if key != "batches" else float(batches))\n        for key in aggregate\n        if key != "batches"\n    }\n\n\ndef _compute_chunk_batch_loss(\n    *,\n    model: PpoTransformerPolicy,\n    batch: dict[str, torch.Tensor],\n    device: torch.device,\n    objective: str,\n    entropy_coef: float,\n    policy_coef: float,\n    value_coef: float,\n    belief_coef: float,\n    oracle_coef: float,\n    reference_model: PpoTransformerPolicy | None,\n    reference_kl_coef: float,\n) -> tuple[torch.Tensor, dict[str, float], int]:\n    token_features = batch["token_features"].to(device)\n    token_mask = batch["token_mask"].to(device)\n    opponent_token_mask = batch["opponent_token_mask"].to(device)\n    option_features = batch["option_features"].to(device)\n    option_mask = batch["option_mask"].to(device)\n    opponent_tag_id = batch["opponent_tag_id"].to(device)\n    opponent_entity_id = batch["opponent_entity_id"].to(device)\n    opponent_deck_id = batch["opponent_deck_id"].to(device)\n    privileged_state = batch["privileged_state"].to(device)\n    belief_histogram_target = batch["belief_histogram_target"].to(device)\n    belief_hand_size_target = batch["belief_hand_size_target"].to(device)\n    belief_remaining_deck_histogram_target = batch["belief_remaining_deck_histogram_target"].to(device)\n    belief_burst_ready_count_target = batch["belief_burst_ready_count_target"].to(device)\n    belief_group_hand_target = batch["belief_group_hand_target"].to(device)\n    belief_group_deck_target = batch["belief_group_deck_target"].to(device)\n    search_self_range_summary = batch["search_self_range_summary"].to(device)\n    search_opponent_range_summary = batch["search_opponent_range_summary"].to(device)\n    search_context_summary = batch["search_context_summary"].to(device)\n    search_teacher_policy_target = batch["search_teacher_policy_target"].to(device)\n    search_teacher_high_policy_target = batch["search_teacher_high_policy_target"].to(device)\n    search_teacher_value_target = batch["search_teacher_value_target"].to(device)\n    search_teacher_weight = batch["search_teacher_weight"].to(device)\n    search_acted = batch["search_acted"].to(device)\n    high_level_mask = batch["high_level_mask"].to(device)\n    action_index = batch["action_index"].to(device)\n    chosen_high_level_code = batch["chosen_high_level_code"].to(device)\n    old_logprob = batch["old_logprob"].to(device)\n    return_target = batch["return_target"].to(device)\n    advantage = batch["advantage"].to(device)\n    sample_weight = batch["sample_weight"].to(device)\n    step_mask = batch["step_mask"].to(device)\n    loss_mask = batch["loss_mask"].to(device)\n\n    batch_size, seq_len = step_mask.shape\n    recurrent_state = (\n        token_features.new_zeros((batch_size, model.config.recurrent_hidden_dim))\n        if model.config.recurrent_hidden_dim > 0\n        else None\n    )\n    reference_recurrent = (\n        token_features.new_zeros((batch_size, reference_model.config.recurrent_hidden_dim))\n        if reference_model is not None and reference_model.config.recurrent_hidden_dim > 0\n        else None\n    )\n    metrics = {\n        "total_loss": 0.0,\n        "policy_loss": 0.0,\n        "high_policy_loss": 0.0,\n        "reference_kl_loss": 0.0,\n        "value_loss": 0.0,\n        "entropy": 0.0,\n        "belief_loss": 0.0,\n        "belief_hand_loss": 0.0,\n        "belief_deck_loss": 0.0,\n        "belief_burst_loss": 0.0,\n        "belief_group_hand_loss": 0.0,\n        "belief_group_deck_loss": 0.0,\n        "search_distill_loss": 0.0,\n        "search_policy_loss": 0.0,\n        "search_value_loss": 0.0,\n        "oracle_loss": 0.0,\n        "oracle_distill_loss": 0.0,\n        "approx_kl": 0.0,\n    }\n    total_loss = token_features.new_zeros(())\n    loss_steps = 0\n    for step_index in range(seq_len):\n        active = step_mask[:, step_index]\n        if not torch.any(active):\n            continue\n        active_indices = torch.nonzero(active, as_tuple=False).squeeze(-1)\n        active_recurrent = recurrent_state.index_select(0, active_indices) if recurrent_state is not None else None\n        step_kwargs = {\n            "token_features": token_features.index_select(0, active_indices)[:, step_index],\n            "token_mask": token_mask.index_select(0, active_indices)[:, step_index],\n            "option_features": option_features.index_select(0, active_indices)[:, step_index],\n            "option_mask": option_mask.index_select(0, active_indices)[:, step_index],\n            "opponent_token_mask": opponent_token_mask.index_select(0, active_indices)[:, step_index],\n            "opponent_tag_ids": opponent_tag_id.index_select(0, active_indices)[:, step_index],\n            "opponent_entity_ids": opponent_entity_id.index_select(0, active_indices)[:, step_index],\n            "opponent_deck_ids": opponent_deck_id.index_select(0, active_indices)[:, step_index],\n            "recurrent_state": active_recurrent,\n        }\n        active_loss = loss_mask[:, step_index].index_select(0, active_indices)\n        if not torch.any(active_loss):\n            with torch.no_grad():\n                burn_output = model(**step_kwargs)\n            if recurrent_state is not None and burn_output.recurrent_state is not None:\n                recurrent_state = recurrent_state.clone()\n                recurrent_state[active_indices] = burn_output.recurrent_state.detach().to(recurrent_state.dtype)\n            if reference_model is not None:\n                reference_kwargs = dict(step_kwargs)\n                if reference_recurrent is not None:\n                    reference_kwargs["recurrent_state"] = reference_recurrent.index_select(0, active_indices)\n                with torch.no_grad():\n                    reference_output = reference_model(**reference_kwargs)\n                if reference_recurrent is not None and reference_output.recurrent_state is not None:\n                    reference_recurrent = reference_recurrent.clone()\n                    reference_recurrent[active_indices] = reference_output.recurrent_state.detach().to(reference_recurrent.dtype)\n            continue\n        output = model(**step_kwargs)\n        if recurrent_state is not None and output.recurrent_state is not None:\n            recurrent_state = recurrent_state.clone()\n            recurrent_state[active_indices] = output.recurrent_state.to(recurrent_state.dtype)\n        local_indices = torch.nonzero(active_loss, as_tuple=False).squeeze(-1)\n        loss_indices = active_indices[local_indices]\n        current_option_mask = step_kwargs["option_mask"][local_indices]\n        step_log_probs = masked_log_softmax(output.policy_logits[local_indices], current_option_mask)\n        step_action_index = action_index.index_select(0, loss_indices)[:, step_index].unsqueeze(-1)\n        selected_logprob = torch.gather(step_log_probs, 1, step_action_index).squeeze(-1)\n        step_old_logprob = old_logprob.index_select(0, loss_indices)[:, step_index]\n        step_returns = return_target.index_select(0, loss_indices)[:, step_index]\n        step_advantages = advantage.index_select(0, loss_indices)[:, step_index]\n        step_weights = sample_weight.index_select(0, loss_indices)[:, step_index]\n        step_search_acted = search_acted.index_select(0, loss_indices)[:, step_index] > 0.0\n        current_high_mask = high_level_mask.index_select(0, loss_indices)[:, step_index]\n        step_high_log_probs = masked_log_softmax(output.high_policy_logits[local_indices], current_high_mask)\n        step_high_codes = chosen_high_level_code.index_select(0, loss_indices)[:, step_index]\n        valid_high = (\n            (step_high_codes >= 0)\n            & (step_high_codes < current_high_mask.shape[1])\n            & torch.gather(current_high_mask, 1, step_high_codes.clamp_min(0).unsqueeze(-1)).squeeze(-1)\n        )\n        if torch.any(valid_high):\n            selected_high_logprob = torch.gather(\n                step_high_log_probs[valid_high],\n                1,\n                step_high_codes[valid_high].unsqueeze(-1),\n            ).squeeze(-1)\n            high_policy_loss = -_weighted_mean(\n                selected_high_logprob,\n                step_weights[valid_high],\n            )\n        else:\n            high_policy_loss = selected_logprob.new_zeros(())\n        step_advantages = (step_advantages - step_advantages.mean()) / step_advantages.std(unbiased=False).clamp_min(1e-6)\n        if objective == "ppo":\n            ppo_active = ~step_search_acted\n            if torch.any(ppo_active):\n                ratio = torch.exp(selected_logprob[ppo_active] - step_old_logprob[ppo_active])\n                clipped_ratio = torch.clamp(ratio, 0.8, 1.2)\n                policy_loss = -_weighted_mean(\n                    torch.min(\n                        ratio * step_advantages[ppo_active],\n                        clipped_ratio * step_advantages[ppo_active],\n                    ),\n                    step_weights[ppo_active],\n                )\n                approx_kl = 0.5 * _weighted_mean(\n                    (selected_logprob[ppo_active] - step_old_logprob[ppo_active]) ** 2,\n                    step_weights[ppo_active],\n                )\n            else:\n                policy_loss = selected_logprob.new_zeros(())\n                approx_kl = selected_logprob.new_zeros(())\n        else:\n            policy_loss = -_weighted_mean(selected_logprob, step_weights) if objective == "behavior_clone" else selected_logprob.new_zeros(())\n            approx_kl = selected_logprob.new_zeros(())\n\n        reference_kl_loss = selected_logprob.new_zeros(())\n        if reference_model is not None and objective == "ppo":\n            reference_kwargs = dict(step_kwargs)\n            if reference_recurrent is not None:\n                reference_kwargs["recurrent_state"] = reference_recurrent.index_select(0, active_indices)\n            with torch.no_grad():\n                reference_output = reference_model(**reference_kwargs)\n                reference_log_probs = masked_log_softmax(\n                    reference_output.policy_logits[local_indices],\n                    current_option_mask,\n                )\n            if reference_recurrent is not None and reference_output.recurrent_state is not None:\n                reference_recurrent = reference_recurrent.clone()\n                reference_recurrent[active_indices] = reference_output.recurrent_state.detach().to(reference_recurrent.dtype)\n            ppo_active = ~step_search_acted\n            if torch.any(ppo_active):\n                current_probs = torch.exp(step_log_probs[ppo_active])\n                reference_kl_loss = _weighted_mean(\n                    (current_probs * (step_log_probs[ppo_active] - reference_log_probs[ppo_active])).sum(dim=-1),\n                    step_weights[ppo_active],\n                )\n\n        current_values = output.partial_value[local_indices]\n        value_loss = _weighted_mean((current_values - step_returns) ** 2, step_weights)\n        oracle_values = model.oracle_value(privileged_state.index_select(0, loss_indices)[:, step_index])\n        oracle_loss = _weighted_mean((oracle_values - step_returns) ** 2, step_weights)\n        oracle_distill_loss = _weighted_mean((current_values - oracle_values.detach()) ** 2, step_weights)\n        current_belief_hist = torch.sigmoid(output.belief_histogram[local_indices])\n        current_belief_deck = torch.sigmoid(output.belief_remaining_deck_histogram[local_indices])\n        target_hist = belief_histogram_target.index_select(0, loss_indices)[:, step_index]\n        target_hand = belief_hand_size_target.index_select(0, loss_indices)[:, step_index]\n        target_deck = belief_remaining_deck_histogram_target.index_select(0, loss_indices)[:, step_index]\n        target_burst = belief_burst_ready_count_target.index_select(0, loss_indices)[:, step_index]\n        target_group_hand = belief_group_hand_target.index_select(0, loss_indices)[:, step_index]\n        target_group_deck = belief_group_deck_target.index_select(0, loss_indices)[:, step_index]\n        current_search_self_range = search_self_range_summary.index_select(0, loss_indices)[:, step_index]\n        current_search_opponent_range = search_opponent_range_summary.index_select(0, loss_indices)[:, step_index]\n        current_search_context = search_context_summary.index_select(0, loss_indices)[:, step_index]\n        target_search_policy = search_teacher_policy_target.index_select(0, loss_indices)[:, step_index]\n        target_search_value = search_teacher_value_target.index_select(0, loss_indices)[:, step_index]\n        target_search_weight = search_teacher_weight.index_select(0, loss_indices)[:, step_index]\n        belief_hist_loss = _weighted_mean(((current_belief_hist - target_hist) ** 2).mean(dim=-1), step_weights)\n        belief_hand_loss = _weighted_mean(\n            F.smooth_l1_loss(output.belief_hand_size[local_indices], target_hand, reduction="none"),\n            step_weights,\n        )\n        belief_deck_loss = _weighted_mean(((current_belief_deck - target_deck) ** 2).mean(dim=-1), step_weights)\n        belief_burst_loss = _weighted_mean(\n            F.smooth_l1_loss(output.belief_burst_ready_count[local_indices], target_burst, reduction="none"),\n            step_weights,\n        )\n        belief_group_hand_loss = _weighted_mean(\n            F.binary_cross_entropy_with_logits(\n                output.belief_group_hand_logits[local_indices],\n                target_group_hand,\n                reduction="none",\n            ).mean(dim=-1),\n            step_weights,\n        )\n        belief_group_deck_loss = _weighted_mean(\n            F.binary_cross_entropy_with_logits(\n                output.belief_group_deck_logits[local_indices],\n                target_group_deck,\n                reduction="none",\n            ).mean(dim=-1),\n            step_weights,\n        )\n        belief_loss = (\n            belief_hist_loss\n            + belief_hand_loss\n            + belief_deck_loss\n            + belief_burst_loss\n            + belief_group_hand_loss\n            + belief_group_deck_loss\n        )\n        search_distill_loss = selected_logprob.new_zeros(())\n        search_policy_loss = selected_logprob.new_zeros(())\n        search_value_loss = selected_logprob.new_zeros(())\n        if objective == "ppo":\n            active_search = target_search_weight > 0.0\n            if torch.any(active_search):\n                search_weights = step_weights[active_search] * target_search_weight[active_search]\n                search_distill_loss = _weighted_mean(\n                    (\n                        -target_search_policy[active_search, : current_option_mask.shape[1]]\n                        * step_log_probs[active_search]\n                    ).sum(dim=-1),\n                    search_weights,\n                )\n                search_option_logits = model.search_option_logits(\n                    option_features=step_kwargs["option_features"][local_indices][active_search],\n                    self_range_summary=current_search_self_range[active_search],\n                    opponent_range_summary=current_search_opponent_range[active_search],\n                    search_context_summary=current_search_context[active_search],\n                )\n                search_log_probs = masked_log_softmax(\n                    search_option_logits,\n                    current_option_mask[active_search],\n                )\n                search_policy_loss = _weighted_mean(\n                    (\n                        -target_search_policy[active_search, : current_option_mask.shape[1]]\n                        * search_log_probs\n                    ).sum(dim=-1),\n                    search_weights,\n                )\n                search_state_values = model.search_state_value(\n                    self_range_summary=current_search_self_range[active_search],\n                    opponent_range_summary=current_search_opponent_range[active_search],\n                    search_context_summary=current_search_context[active_search],\n                )\n                search_value_loss = _weighted_mean(\n                    (search_state_values - target_search_value[active_search]) ** 2,\n                    search_weights,\n                )\n                target_search_high_policy = search_teacher_high_policy_target.index_select(0, loss_indices)[:, step_index]\n                high_policy_loss = high_policy_loss + _weighted_mean(\n                    (\n                        -target_search_high_policy[active_search]\n                        * step_high_log_probs[active_search]\n                    ).sum(dim=-1),\n                    search_weights,\n                )\n        entropy = _weighted_mean((-(torch.exp(step_log_probs) * step_log_probs).sum(dim=-1)), step_weights)\n        step_total = (\n            (policy_coef * policy_loss)\n            + high_policy_loss\n            + (value_coef * value_loss)\n            + (belief_coef * belief_loss)\n            + search_distill_loss\n            + search_policy_loss\n            + search_value_loss\n            + (oracle_coef * (oracle_loss + oracle_distill_loss))\n            + (reference_kl_coef * reference_kl_loss)\n            - (entropy_coef * entropy if objective == "ppo" else 0.0)\n        )\n        total_loss = total_loss + step_total\n        metrics["policy_loss"] += float(policy_loss.item())\n        metrics["high_policy_loss"] += float(high_policy_loss.item())\n        metrics["reference_kl_loss"] += float(reference_kl_loss.item())\n        metrics["value_loss"] += float(value_loss.item())\n        metrics["entropy"] += float(entropy.item())\n        metrics["belief_loss"] += float(belief_loss.item())\n        metrics["belief_hand_loss"] += float(belief_hand_loss.item())\n        metrics["belief_deck_loss"] += float(belief_deck_loss.item())\n        metrics["belief_burst_loss"] += float(belief_burst_loss.item())\n        metrics["belief_group_hand_loss"] += float(belief_group_hand_loss.item())\n        metrics["belief_group_deck_loss"] += float(belief_group_deck_loss.item())\n        metrics["search_distill_loss"] += float(search_distill_loss.item())\n        metrics["search_policy_loss"] += float(search_policy_loss.item())\n        metrics["search_value_loss"] += float(search_value_loss.item())\n        metrics["oracle_loss"] += float(oracle_loss.item())\n        metrics["oracle_distill_loss"] += float(oracle_distill_loss.item())\n        metrics["approx_kl"] += float(approx_kl.item())\n        loss_steps += 1\n    if loss_steps <= 0:\n        raise RuntimeError("no valid loss steps found in chunk batch")\n    for key in metrics:\n        metrics[key] /= loss_steps\n    metrics["total_loss"] = float(total_loss.item()) / loss_steps\n    return total_loss / loss_steps, metrics, loss_steps\n\n\ndef _slice_chunk_batch(batch: dict[str, torch.Tensor], start: int, stop: int) -> dict[str, torch.Tensor]:\n    return {key: value[start:stop] for key, value in batch.items()}\n\n\ndef _resolve_micro_batch_size(\n    *,\n    batch_size: int,\n    requested_micro_batch_size: int | None,\n    param_count: int,\n    device: torch.device,\n) -> int:\n    if batch_size <= 0:\n        return 1\n    if requested_micro_batch_size is not None:\n        return max(1, min(batch_size, int(requested_micro_batch_size)))\n    if device.type != "cuda":\n        return batch_size\n    if param_count >= 30_000_000:\n        return min(batch_size, 8)\n    if param_count >= 20_000_000:\n        return min(batch_size, 12)\n    if param_count >= 10_000_000:\n        return min(batch_size, 16)\n    return batch_size\n\n\ndef _load_reference_model(\n    checkpoint_path: str | Path | None,\n    *,\n    device: str,\n) -> PpoTransformerPolicy | None:\n    if checkpoint_path is None:\n        return None\n    reference_path = Path(checkpoint_path)\n    if not reference_path.exists():\n        return None\n    try:\n        model, _, _, _ = load_ppo_training_checkpoint(reference_path, device=device)\n    except Exception:\n        model, _, _ = load_ppo_deployment_checkpoint(reference_path, device=device)\n    model.eval()\n    for parameter in model.parameters():\n        parameter.requires_grad_(False)\n    return model\n\n\ndef _collate_chunks(chunks: Sequence[PpoTrainChunk]) -> dict[str, torch.Tensor]:\n    batch_size = len(chunks)\n    max_seq_len = max(len(chunk.steps) for chunk in chunks)\n    first = chunks[0].steps[0]\n    max_tokens = max(len(step.token_features) for chunk in chunks for step in chunk.steps)\n    max_options = max(len(step.option_features) for chunk in chunks for step in chunk.steps)\n    token_dim = len(first.token_features[0])\n    option_dim = len(first.option_features[0])\n    privileged_dim = len(first.privileged_state)\n    belief_dim = len(first.belief_histogram_target)\n    belief_deck_dim = len(first.belief_remaining_deck_histogram_target)\n    belief_group_dim = len(first.belief_group_hand_target)\n    search_range_dim = len(first.search_self_range_summary)\n    search_context_dim = len(first.search_context_summary)\n    high_action_dim = len(first.high_level_mask)\n\n    token_features = torch.zeros((batch_size, max_seq_len, max_tokens, token_dim), dtype=torch.float32)\n    token_mask = torch.zeros((batch_size, max_seq_len, max_tokens), dtype=torch.bool)\n    opponent_token_mask = torch.zeros((batch_size, max_seq_len, max_tokens), dtype=torch.bool)\n    option_features = torch.zeros((batch_size, max_seq_len, max_options, option_dim), dtype=torch.float32)\n    option_mask = torch.zeros((batch_size, max_seq_len, max_options), dtype=torch.bool)\n    privileged_state = torch.zeros((batch_size, max_seq_len, privileged_dim), dtype=torch.float32)\n    belief_histogram_target = torch.zeros((batch_size, max_seq_len, belief_dim), dtype=torch.float32)\n    belief_hand_size_target = torch.zeros((batch_size, max_seq_len), dtype=torch.float32)\n    belief_remaining_deck_histogram_target = torch.zeros((batch_size, max_seq_len, belief_deck_dim), dtype=torch.float32)\n    belief_burst_ready_count_target = torch.zeros((batch_size, max_seq_len), dtype=torch.float32)\n    belief_group_hand_target = torch.zeros((batch_size, max_seq_len, belief_group_dim), dtype=torch.float32)\n    belief_group_deck_target = torch.zeros((batch_size, max_seq_len, belief_group_dim), dtype=torch.float32)\n    search_self_range_summary = torch.zeros((batch_size, max_seq_len, search_range_dim), dtype=torch.float32)\n    search_opponent_range_summary = torch.zeros((batch_size, max_seq_len, search_range_dim), dtype=torch.float32)\n    search_context_summary = torch.zeros((batch_size, max_seq_len, search_context_dim), dtype=torch.float32)\n    search_teacher_policy_target = torch.zeros((batch_size, max_seq_len, max_options), dtype=torch.float32)\n    search_teacher_high_policy_target = torch.zeros((batch_size, max_seq_len, high_action_dim), dtype=torch.float32)\n    search_teacher_value_target = torch.zeros((batch_size, max_seq_len), dtype=torch.float32)\n    search_teacher_weight = torch.zeros((batch_size, max_seq_len), dtype=torch.float32)\n    search_acted = torch.zeros((batch_size, max_seq_len), dtype=torch.float32)\n    high_level_mask = torch.zeros((batch_size, max_seq_len, high_action_dim), dtype=torch.bool)\n    opponent_tag_id = torch.zeros((batch_size, max_seq_len), dtype=torch.long)\n    opponent_entity_id = torch.zeros((batch_size, max_seq_len), dtype=torch.long)\n    opponent_deck_id = torch.zeros((batch_size, max_seq_len), dtype=torch.long)\n    action_index = torch.zeros((batch_size, max_seq_len), dtype=torch.long)\n    chosen_high_level_code = torch.full((batch_size, max_seq_len), -1, dtype=torch.long)\n    old_logprob = torch.zeros((batch_size, max_seq_len), dtype=torch.float32)\n    return_target = torch.zeros((batch_size, max_seq_len), dtype=torch.float32)\n    advantage = torch.zeros((batch_size, max_seq_len), dtype=torch.float32)\n    sample_weight = torch.ones((batch_size, max_seq_len), dtype=torch.float32)\n    step_mask = torch.zeros((batch_size, max_seq_len), dtype=torch.bool)\n    loss_mask = torch.zeros((batch_size, max_seq_len), dtype=torch.bool)\n\n    for batch_index, chunk in enumerate(chunks):\n        for step_index, step in enumerate(chunk.steps):\n            token_count = len(step.token_features)\n            option_count = len(step.option_features)\n            token_features[batch_index, step_index, :token_count] = torch.as_tensor(step.token_features, dtype=torch.float32)\n            token_mask[batch_index, step_index, :token_count] = True\n            opponent_token_mask[batch_index, step_index, :token_count] = torch.as_tensor(\n                step.opponent_token_mask,\n                dtype=torch.bool,\n            )\n            option_features[batch_index, step_index, :option_count] = torch.as_tensor(\n                step.option_features,\n                dtype=torch.float32,\n            )\n            option_mask[batch_index, step_index, :option_count] = True\n            privileged_state[batch_index, step_index] = torch.as_tensor(step.privileged_state, dtype=torch.float32)\n            belief_histogram_target[batch_index, step_index] = torch.as_tensor(\n                step.belief_histogram_target,\n                dtype=torch.float32,\n            )\n            belief_hand_size_target[batch_index, step_index] = float(step.belief_hand_size_target)\n            belief_remaining_deck_histogram_target[batch_index, step_index] = torch.as_tensor(\n                step.belief_remaining_deck_histogram_target,\n                dtype=torch.float32,\n            )\n            belief_burst_ready_count_target[batch_index, step_index] = float(step.belief_burst_ready_count_target)\n            belief_group_hand_target[batch_index, step_index] = torch.as_tensor(\n                step.belief_group_hand_target,\n                dtype=torch.float32,\n            )\n            belief_group_deck_target[batch_index, step_index] = torch.as_tensor(\n                step.belief_group_deck_target,\n                dtype=torch.float32,\n            )\n            search_self_range_summary[batch_index, step_index] = torch.as_tensor(\n                step.search_self_range_summary,\n                dtype=torch.float32,\n            )\n            search_opponent_range_summary[batch_index, step_index] = torch.as_tensor(\n                step.search_opponent_range_summary,\n                dtype=torch.float32,\n            )\n            search_context_summary[batch_index, step_index] = torch.as_tensor(\n                step.search_context_summary,\n                dtype=torch.float32,\n            )\n            if step.search_teacher_policy_target:\n                search_teacher_policy_target[batch_index, step_index, : len(step.search_teacher_policy_target)] = torch.as_tensor(\n                    step.search_teacher_policy_target,\n                    dtype=torch.float32,\n                )\n            if step.search_teacher_high_policy_target:\n                search_teacher_high_policy_target[batch_index, step_index, : len(step.search_teacher_high_policy_target)] = torch.as_tensor(\n                    step.search_teacher_high_policy_target,\n                    dtype=torch.float32,\n                )\n            search_teacher_value_target[batch_index, step_index] = float(step.search_teacher_value_target)\n            search_teacher_weight[batch_index, step_index] = float(step.search_teacher_weight)\n            search_acted[batch_index, step_index] = float(step.search_acted)\n            if step.high_level_mask:\n                high_level_mask[batch_index, step_index, : len(step.high_level_mask)] = torch.as_tensor(\n                    step.high_level_mask,\n                    dtype=torch.bool,\n                )\n            opponent_tag_id[batch_index, step_index] = int(step.opponent_tag_id)\n            opponent_entity_id[batch_index, step_index] = int(step.opponent_entity_id)\n            opponent_deck_id[batch_index, step_index] = int(step.opponent_deck_id)\n            action_index[batch_index, step_index] = int(step.action_index)\n            chosen_high_level_code[batch_index, step_index] = int(step.chosen_high_level_code)\n            old_logprob[batch_index, step_index] = float(step.old_logprob)\n            return_target[batch_index, step_index] = float(step.return_target)\n            advantage[batch_index, step_index] = float(step.advantage)\n            sample_weight[batch_index, step_index] = float(step.sample_weight)\n            step_mask[batch_index, step_index] = True\n        loss_start = min(chunk.burn_in, len(chunk.steps))\n        loss_end = min(len(chunk.steps), loss_start + chunk.loss_length)\n        if loss_end > loss_start:\n            loss_mask[batch_index, loss_start:loss_end] = True\n\n    return {\n        "token_features": token_features,\n        "token_mask": token_mask,\n        "opponent_token_mask": opponent_token_mask,\n        "option_features": option_features,\n        "option_mask": option_mask,\n        "privileged_state": privileged_state,\n        "belief_histogram_target": belief_histogram_target,\n        "belief_hand_size_target": belief_hand_size_target,\n        "belief_remaining_deck_histogram_target": belief_remaining_deck_histogram_target,\n        "belief_burst_ready_count_target": belief_burst_ready_count_target,\n        "belief_group_hand_target": belief_group_hand_target,\n        "belief_group_deck_target": belief_group_deck_target,\n        "search_self_range_summary": search_self_range_summary,\n        "search_opponent_range_summary": search_opponent_range_summary,\n        "search_context_summary": search_context_summary,\n        "search_teacher_policy_target": search_teacher_policy_target,\n        "search_teacher_high_policy_target": search_teacher_high_policy_target,\n        "search_teacher_value_target": search_teacher_value_target,\n        "search_teacher_weight": search_teacher_weight,\n        "search_acted": search_acted,\n        "high_level_mask": high_level_mask,\n        "opponent_tag_id": opponent_tag_id,\n        "opponent_entity_id": opponent_entity_id,\n        "opponent_deck_id": opponent_deck_id,\n        "action_index": action_index,\n        "chosen_high_level_code": chosen_high_level_code,\n        "old_logprob": old_logprob,\n        "return_target": return_target,\n        "advantage": advantage,\n        "sample_weight": sample_weight,\n        "step_mask": step_mask,\n        "loss_mask": loss_mask,\n    }\n\n\ndef _dataset_ratios(\n    *,\n    fresh_chunks: Sequence[PpoTrainChunk],\n    replay_chunks: Sequence[PpoTrainChunk],\n) -> dict[str, float]:\n    all_chunks = list(fresh_chunks) + list(replay_chunks)\n    if not all_chunks:\n        return {\n            "late_round_sample_ratio": 0.0,\n            "draw_chunk_ratio": 0.0,\n            "loss_chunk_ratio": 0.0,\n        }\n    total = float(len(all_chunks))\n    return {\n        "late_round_sample_ratio": sum(1 for chunk in all_chunks if chunk.has_late_round) / total,\n        "draw_chunk_ratio": sum(1 for chunk in all_chunks if chunk.has_terminal_draw) / total,\n        "loss_chunk_ratio": sum(1 for chunk in all_chunks if chunk.has_terminal_loss) / total,\n    }\n\n\ndef _context_from_step(step: TrajectoryStep, *, episode_metadata: dict[str, object] | None = None) -> DecisionContext:\n    metadata = dict(episode_metadata or {})\n    metadata.update(step.metadata)\n    return DecisionContext(\n        acting_player=step.acting_player,\n        request_type=step.request_type,\n        step_index=0,\n        full_state=step.pre_state,\n        legal_low_level_codes=step.legal_low_level_codes,\n        legal_low_level_specs=step.legal_low_level_specs,\n        legal_low_level_mask=step.legal_low_level_mask,\n        legal_high_level_codes=step.legal_high_level_codes,\n        high_to_low_map=step.high_to_low_map,\n        player_view=step.player_view,\n        full_state_json=step.full_state_json_before,\n        terminal=False,\n        metadata=metadata,\n    )\n\n\ndef _selected_action_index(step: TrajectoryStep) -> int:\n    selected_code = selected_low_level_code(step)\n    if selected_code is None:\n        raise KeyError("selected action code could not be derived from trajectory step")\n    legal_codes = (\n        tuple(int(code) for code in step.legal_low_level_codes)\n        if step.legal_low_level_codes\n        else tuple(int(spec.action_code) for spec in legal_low_level_specs(_context_from_step(step)))\n    )\n    for index, action_code in enumerate(legal_codes):\n        if int(action_code) == selected_code:\n            return index\n    raise KeyError(f"selected action_code {selected_code} not found in legal low-level codes")\n\n\ndef _gae_returns(\n    transitions: Sequence[_DecisionTransition],\n    *,\n    gae_lambda: float,\n) -> tuple[list[float], list[float]]:\n    returns = [0.0] * len(transitions)\n    advantages = [0.0] * len(transitions)\n    gae = 0.0\n    for index in reversed(range(len(transitions))):\n        transition = transitions[index]\n        delta = transition.reward + (transition.discount * transition.next_value) - transition.value\n        gae = delta + (transition.discount * gae_lambda * gae)\n        advantages[index] = gae\n        returns[index] = gae + transition.value\n    return returns, advantages\n\n\ndef _accumulate_reward_until_next_trainable(\n    steps: Sequence[TrajectoryStep],\n    *,\n    start_index: int,\n    next_trainable_index: int | None,\n    perspective_player: int,\n    gamma: float,\n) -> tuple[float, float]:\n    reward = 0.0\n    discount = 1.0\n    for index in range(start_index, len(steps)):\n        step = steps[index]\n        reward += discount * _shaped_reward(\n            step,\n            perspective_player=perspective_player,\n            gamma=gamma,\n        )\n        if step.done:\n            return reward, 0.0\n        discount *= gamma\n        if next_trainable_index is not None and (index + 1) >= next_trainable_index:\n            return reward, discount\n    return reward, 0.0\n\n\ndef _shaped_reward(\n    step: TrajectoryStep,\n    *,\n    perspective_player: int,\n    gamma: float,\n) -> float:\n    base_reward = _terminal_reward(step, perspective_player=perspective_player)\n    phi_before = _potential(step.pre_state, perspective_player=perspective_player)\n    phi_after = _potential(step.post_state, perspective_player=perspective_player)\n    shaping = (gamma * phi_after) - phi_before\n    return (\n        base_reward\n        + shaping\n        + _anti_draw_penalty(step.post_state.round_number)\n        + _action_efficiency_reward(step, perspective_player=perspective_player)\n    )\n\n\ndef _terminal_reward(step: TrajectoryStep, *, perspective_player: int) -> float:\n    if not step.done:\n        return 0.0\n    winner = step.post_state.winner\n    if winner == perspective_player:\n        return 1.0\n    return -1.0\n\n\ndef _potential(state, *, perspective_player: int) -> float:\n    self_player = state.players[perspective_player]\n    opponent = state.players[1 - perspective_player]\n    self_hp = sum(character.health for character in self_player.characters)\n    opp_hp = sum(character.health for character in opponent.characters)\n    self_alive = sum(0 if character.defeated else 1 for character in self_player.characters)\n    opp_alive = sum(0 if character.defeated else 1 for character in opponent.characters)\n    self_energy = sum(character.energy for character in self_player.characters)\n    opp_energy = sum(character.energy for character in opponent.characters)\n    self_board = len(self_player.combat_statuses) + len(self_player.summons) + len(self_player.supports)\n    opp_board = len(opponent.combat_statuses) + len(opponent.summons) + len(opponent.supports)\n    return (\n        0.6 * ((self_hp - opp_hp) / 30.0)\n        + 0.2 * ((self_alive - opp_alive) / 3.0)\n        + 0.1 * ((self_energy - opp_energy) / 6.0)\n        + 0.1 * ((self_board - opp_board) / 10.0)\n    )\n\n\ndef _anti_draw_penalty(round_number: int) -> float:\n    if round_number >= 15:\n        return -0.10\n    if round_number == 14:\n        return -0.05\n    if round_number == 13:\n        return -0.02\n    return 0.0\n\n\ndef _action_efficiency_reward(step: TrajectoryStep, *, perspective_player: int) -> float:\n    severity = premature_end_severity(step)\n    if severity <= 0.0:\n        return 0.0\n    waste_ratio = declare_end_waste_ratio(step)\n    advantage = max(0.0, min(1.0, _potential(step.pre_state, perspective_player=perspective_player)))\n    # When the current player is already clearly ahead, ending the turn can be a\n    # valid simplification. Keep the prior mild and attenuate it in winning states.\n    attenuation = max(0.2, 1.0 - (0.8 * advantage))\n    return severity * attenuation * (-0.03 - (0.03 * waste_ratio))\n\n\ndef _sample_weight(\n    *,\n    episode: EpisodeRecord,\n    perspective_player: int,\n    round_number: int,\n) -> float:\n    weight = 1.0\n    if round_number >= 13:\n        weight += 1.0\n    if episode.winner is None or episode.winner != perspective_player:\n        weight += 1.0\n    return min(3.0, weight)\n\n\ndef _weighted_mean(values: torch.Tensor, weights: torch.Tensor) -> torch.Tensor:\n    denom = weights.sum().clamp_min(1e-6)\n    return torch.sum(values * weights) / denom\n'


def main() -> None:
    parser = argparse.ArgumentParser(description="Apply the corrected four-file patch based only on the latest uploaded files.")
    parser.add_argument("--action-adapter", required=True)
    parser.add_argument("--action-hierarchy", required=True)
    parser.add_argument("--ppo-training", required=True)
    parser.add_argument("--lookahead-search", required=True)
    args = parser.parse_args()

    targets = {
        Path(args.action_adapter): ACTION_ADAPTER_CONTENT,
        Path(args.action_hierarchy): ACTION_HIERARCHY_CONTENT,
        Path(args.ppo_training): PPO_TRAINING_CONTENT,
        Path(args.lookahead_search): LOOKAHEAD_SEARCH_CONTENT,
    }

    for path, content in targets.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        print(f"patched: {path}")


if __name__ == "__main__":
    main()
